//! Terminal cell buffer with style patching semantics.

use crate::unicode::{graphemes, str_width};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Color {
    Reset,
    Yellow,
    Rgb(u8, u8, u8),
}

pub const BOLD: u16 = 0b0000_0000_0001;
pub const DIM: u16 = 0b0000_0000_0010;
pub const ITALIC: u16 = 0b0000_0000_0100;
pub const UNDERLINED: u16 = 0b0000_0000_1000;
pub const SLOW_BLINK: u16 = 0b0000_0001_0000;
pub const RAPID_BLINK: u16 = 0b0000_0010_0000;
pub const REVERSED: u16 = 0b0000_0100_0000;
pub const HIDDEN: u16 = 0b0000_1000_0000;
pub const CROSSED_OUT: u16 = 0b0001_0000_0000;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub add_modifier: u16,
    pub sub_modifier: u16,
}

impl Style {
    pub fn new() -> Style {
        Style::default()
    }
    pub fn fg(mut self, c: Color) -> Style {
        self.fg = Some(c);
        self
    }
    pub fn bg(mut self, c: Color) -> Style {
        self.bg = Some(c);
        self
    }
    pub fn add_modifier(mut self, m: u16) -> Style {
        self.sub_modifier &= !m;
        self.add_modifier |= m;
        self
    }
    pub fn bold(self) -> Style {
        self.add_modifier(BOLD)
    }
    pub fn patch(self, other: Style) -> Style {
        Style {
            fg: other.fg.or(self.fg),
            bg: other.bg.or(self.bg),
            add_modifier: (self.add_modifier & !other.sub_modifier) | other.add_modifier,
            sub_modifier: (self.sub_modifier & !other.add_modifier) | other.sub_modifier,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Cell {
    pub symbol: String,
    pub fg: Color,
    pub bg: Color,
    pub modifier: u16,
}

impl Default for Cell {
    fn default() -> Self {
        Cell {
            symbol: " ".to_string(),
            fg: Color::Reset,
            bg: Color::Reset,
            modifier: 0,
        }
    }
}

impl Cell {
    pub fn set_symbol(&mut self, s: &str) -> &mut Cell {
        self.symbol.clear();
        self.symbol.push_str(s);
        self
    }
    pub fn append_symbol(&mut self, s: &str) -> &mut Cell {
        self.symbol.push_str(s);
        self
    }
    pub fn set_style(&mut self, style: Style) -> &mut Cell {
        if let Some(c) = style.fg {
            self.fg = c;
        }
        if let Some(c) = style.bg {
            self.bg = c;
        }
        self.modifier |= style.add_modifier;
        self.modifier &= !style.sub_modifier;
        self
    }
    pub fn reset(&mut self) {
        self.symbol.clear();
        self.symbol.push(' ');
        self.fg = Color::Reset;
        self.bg = Color::Reset;
        self.modifier = 0;
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Rect {
    pub x: u16,
    pub y: u16,
    pub width: u16,
    pub height: u16,
}

impl Rect {
    pub fn new(x: u16, y: u16, width: u16, height: u16) -> Rect {
        // clamp so that x + width and y + height do not overflow
        let width = width.min(u16::MAX - x);
        let height = height.min(u16::MAX - y);
        Rect { x, y, width, height }
    }
    pub fn left(&self) -> u16 {
        self.x
    }
    pub fn right(&self) -> u16 {
        self.x.saturating_add(self.width)
    }
    pub fn top(&self) -> u16 {
        self.y
    }
    pub fn bottom(&self) -> u16 {
        self.y.saturating_add(self.height)
    }
    pub fn area(&self) -> u32 {
        self.width as u32 * self.height as u32
    }
    pub fn is_empty(&self) -> bool {
        self.width == 0 || self.height == 0
    }
    pub fn intersection(&self, other: Rect) -> Rect {
        let x1 = self.x.max(other.x);
        let y1 = self.y.max(other.y);
        let x2 = self.right().min(other.right());
        let y2 = self.bottom().min(other.bottom());
        Rect {
            x: x1,
            y: y1,
            width: x2.saturating_sub(x1),
            height: y2.saturating_sub(y1),
        }
    }
    pub fn indent_x(&self, offset: u16) -> Rect {
        Rect {
            x: self.x.saturating_add(offset),
            width: self.width.saturating_sub(offset),
            ..*self
        }
    }
}

#[derive(Clone, Debug)]
pub struct Buffer {
    pub area: Rect,
    pub content: Vec<Cell>,
}

impl Buffer {
    pub fn empty(area: Rect) -> Buffer {
        Buffer {
            area,
            content: vec![Cell::default(); area.area() as usize],
        }
    }

    pub fn index_of(&self, x: u16, y: u16) -> usize {
        ((y - self.area.y) as usize) * self.area.width as usize + (x - self.area.x) as usize
    }

    pub fn pos_of(&self, i: usize) -> (u16, u16) {
        let w = self.area.width as usize;
        (self.area.x + (i % w) as u16, self.area.y + (i / w) as u16)
    }

    pub fn contains(&self, x: u16, y: u16) -> bool {
        x >= self.area.left() && x < self.area.right() && y >= self.area.top() && y < self.area.bottom()
    }

    pub fn cell_mut(&mut self, x: u16, y: u16) -> Option<&mut Cell> {
        if self.contains(x, y) {
            let i = self.index_of(x, y);
            Some(&mut self.content[i])
        } else {
            None
        }
    }

    pub fn reset(&mut self) {
        for c in self.content.iter_mut() {
            c.reset();
        }
    }

    pub fn resize(&mut self, area: Rect) {
        self.area = area;
        self.content = vec![Cell::default(); area.area() as usize];
    }

    pub fn set_style(&mut self, area: Rect, style: Style) {
        let area = self.area.intersection(area);
        for y in area.top()..area.bottom() {
            for x in area.left()..area.right() {
                let i = self.index_of(x, y);
                self.content[i].set_style(style);
            }
        }
    }

    /// Print at most `max_width` columns of `string`, returning the next position.
    pub fn set_stringn(&mut self, mut x: u16, y: u16, string: &str, max_width: usize, style: Style) -> (u16, u16) {
        if !self.contains(x, y) && !(x == self.area.right() && y >= self.area.top() && y < self.area.bottom()) {
            return (x, y);
        }
        let max_width = u16::try_from(max_width).unwrap_or(u16::MAX);
        let mut remaining_width = self.area.right().saturating_sub(x).min(max_width);
        for symbol in graphemes(string) {
            if symbol.chars().any(|c| c.is_control()) {
                continue;
            }
            let width = str_width(symbol) as u16;
            if width == 0 {
                continue;
            }
            match remaining_width.checked_sub(width) {
                Some(r) => remaining_width = r,
                None => break,
            }
            if let Some(cell) = self.cell_mut(x, y) {
                cell.set_symbol(symbol).set_style(style);
            }
            let next_symbol = x + width;
            x += 1;
            while x < next_symbol {
                if let Some(cell) = self.cell_mut(x, y) {
                    cell.reset();
                }
                x += 1;
            }
        }
        (x, y)
    }

    /// Compute the list of cells that differ between `self` (previous) and `other` (next).
    pub fn diff<'a>(&self, other: &'a Buffer) -> Vec<(u16, u16, &'a Cell)> {
        let previous = &self.content;
        let next = &other.content;
        let mut updates = Vec::new();
        let mut invalidated: usize = 0;
        let mut to_skip: usize = 0;
        for (i, (current, prev)) in next.iter().zip(previous.iter()).enumerate() {
            if (current != prev || invalidated > 0) && to_skip == 0 {
                let (x, y) = other.pos_of(i);
                updates.push((x, y, &next[i]));
            }
            let cw = str_width(&current.symbol);
            let pw = str_width(&prev.symbol);
            to_skip = cw.saturating_sub(1);
            let affected = cw.max(pw);
            invalidated = affected.max(invalidated).saturating_sub(1);
        }
        updates
    }
}
