use crate::buffer::{Buffer, Rect, Style};
use crate::unicode::{graphemes, str_width};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Alignment {
    Left,
    Center,
    Right,
}

#[derive(Clone, Debug, Default)]
pub struct Span {
    pub content: String,
    pub style: Style,
}

impl Span {
    pub fn raw<S: Into<String>>(s: S) -> Span {
        Span { content: s.into(), style: Style::default() }
    }
    pub fn styled<S: Into<String>>(s: S, style: Style) -> Span {
        Span { content: s.into(), style }
    }
    pub fn width(&self) -> usize {
        str_width(&self.content)
    }
    pub fn styled_graphemes(&self, base: Style) -> Vec<StyledGrapheme<'_>> {
        let style = base.patch(self.style);
        graphemes(&self.content)
            .into_iter()
            .filter(|g| *g != "\n")
            .map(|g| StyledGrapheme { symbol: g, style })
            .collect()
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        if area.is_empty() {
            return;
        }
        let mut x = area.x;
        let y = area.y;
        for (i, g) in self.styled_graphemes(Style::default()).into_iter().enumerate() {
            let symbol_width = str_width(g.symbol);
            let next_x = x.saturating_add(symbol_width as u16);
            if next_x > area.right() {
                break;
            }
            if i == 0 {
                if let Some(c) = buf.cell_mut(x, y) {
                    c.set_symbol(g.symbol).set_style(g.style);
                }
            } else if x == area.x {
                if let Some(c) = buf.cell_mut(x, y) {
                    c.append_symbol(g.symbol).set_style(g.style);
                }
            } else if symbol_width == 0 {
                if let Some(c) = buf.cell_mut(x - 1, y) {
                    c.append_symbol(g.symbol).set_style(g.style);
                }
            } else if let Some(c) = buf.cell_mut(x, y) {
                c.set_symbol(g.symbol).set_style(g.style);
            }
            for xh in (x + 1)..next_x {
                if let Some(c) = buf.cell_mut(xh, y) {
                    c.reset();
                }
            }
            x = next_x;
        }
    }
}

#[derive(Clone, Copy, Debug)]
pub struct StyledGrapheme<'a> {
    pub symbol: &'a str,
    pub style: Style,
}

#[derive(Clone, Debug, Default)]
pub struct Line {
    pub spans: Vec<Span>,
    pub style: Style,
    pub alignment: Option<Alignment>,
}

impl Line {
    pub fn from_spans(spans: Vec<Span>) -> Line {
        Line { spans, style: Style::default(), alignment: None }
    }
    pub fn raw<S: Into<String>>(s: S) -> Line {
        Line::from_spans(vec![Span::raw(s)])
    }
    pub fn width(&self) -> usize {
        self.spans.iter().map(|s| s.width()).sum()
    }
    pub fn styled_graphemes(&self, base: Style) -> Vec<StyledGrapheme<'_>> {
        let style = base.patch(self.style);
        self.spans.iter().flat_map(|s| s.styled_graphemes(style)).collect()
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        self.render_with_alignment(area, buf, None);
    }

    pub fn render_with_alignment(&self, area: Rect, buf: &mut Buffer, parent: Option<Alignment>) {
        let area = area.intersection(buf.area);
        if area.is_empty() {
            return;
        }
        let area = Rect { height: 1, ..area };
        let line_width = self.width();
        if line_width == 0 {
            return;
        }
        buf.set_style(area, self.style);
        let alignment = self.alignment.or(parent);
        let area_width = area.width as usize;
        if line_width <= area_width {
            let indent = match alignment {
                Some(Alignment::Center) => area_width.saturating_sub(line_width) / 2,
                Some(Alignment::Right) => area_width.saturating_sub(line_width),
                _ => 0,
            };
            let indent = u16::try_from(indent).unwrap_or(u16::MAX);
            render_spans(&self.spans, area.indent_x(indent), buf, 0);
        } else {
            let skip = match alignment {
                Some(Alignment::Center) => line_width.saturating_sub(area_width) / 2,
                Some(Alignment::Right) => line_width.saturating_sub(area_width),
                _ => 0,
            };
            render_spans(&self.spans, area, buf, skip);
        }
    }
}

fn render_spans(spans: &[Span], mut area: Rect, buf: &mut Buffer, span_skip_width: usize) {
    // Compute spans after skipping `span_skip_width` columns.
    let mut skip = span_skip_width;
    for span in spans {
        let span_width = span.width();
        if skip >= span_width && skip > 0 {
            skip -= span_width;
            continue;
        }
        let (render_span, offset, rendered_width) = if skip > 0 {
            // partially skip this span
            let mut content = String::new();
            let mut skipped = 0usize;
            let mut first_offset = 0usize;
            let mut started = false;
            for g in graphemes(&span.content) {
                let w = str_width(g);
                if !started {
                    if skipped + w <= skip {
                        skipped += w;
                        continue;
                    }
                    started = true;
                    // a wide grapheme straddling the skip boundary is replaced by an offset
                    if skipped < skip {
                        first_offset = skipped + w - skip;
                        skipped += w;
                        continue;
                    }
                }
                content.push_str(g);
            }
            let w = str_width(&content);
            skip = 0;
            (Span::styled(content, span.style), first_offset, w)
        } else {
            (span.clone(), 0usize, span_width)
        };
        area = area.indent_x(offset as u16);
        if area.is_empty() {
            break;
        }
        render_span.render(area, buf);
        let w = u16::try_from(rendered_width).unwrap_or(u16::MAX);
        area = area.indent_x(w);
    }
}

#[derive(Clone, Debug, Default)]
pub struct Text {
    pub lines: Vec<Line>,
    pub style: Style,
    pub alignment: Option<Alignment>,
}

impl Text {
    pub fn from_lines(lines: Vec<Line>) -> Text {
        Text { lines, style: Style::default(), alignment: None }
    }
    pub fn raw<S: AsRef<str>>(s: S) -> Text {
        // split on newlines like ratatui does
        let s = s.as_ref();
        let lines: Vec<Line> = if s.is_empty() {
            vec![Line::default()]
        } else {
            s.lines().map(|l| Line::raw(l.to_string())).collect()
        };
        Text::from_lines(lines)
    }
    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        buf.set_style(area, self.style);
        for (i, line) in self.lines.iter().enumerate() {
            if i as u16 >= area.height {
                break;
            }
            let line_area = Rect { x: area.x, y: area.y + i as u16, width: area.width, height: 1 };
            line.render_with_alignment(line_area, buf, self.alignment);
        }
    }
}
EOF
