//! Widgets: Block, Paragraph (with word wrapping) and Table.

use std::collections::VecDeque;

use crate::buffer::{Buffer, Rect, Style};
use crate::layout::{split, Constraint};
use crate::text::{Alignment, Line, StyledGrapheme, Text};
use crate::unicode::{is_whitespace_grapheme, str_width};

// ---------------------------------------------------------------------------
// Block

pub const BORDER_TOP: u8 = 1;
pub const BORDER_BOTTOM: u8 = 2;

#[derive(Clone, Debug, Default)]
pub struct Block {
    pub borders: u8,
    pub titles: Vec<Line>,
}

impl Block {
    pub fn new(borders: u8) -> Block {
        Block { borders, titles: Vec::new() }
    }
    pub fn title(mut self, line: Line) -> Block {
        self.titles.push(line);
        self
    }
    pub fn inner(&self, area: Rect) -> Rect {
        let mut inner = area;
        if self.borders & BORDER_TOP != 0 || !self.titles.is_empty() {
            inner.y = inner.y.saturating_add(1).min(inner.bottom());
            inner.height = inner.height.saturating_sub(1);
        }
        if self.borders & BORDER_BOTTOM != 0 {
            inner.height = inner.height.saturating_sub(1);
        }
        inner
    }
    pub fn vertical_space(&self) -> (u16, u16) {
        let top = if self.borders & BORDER_TOP != 0 || !self.titles.is_empty() { 1 } else { 0 };
        let bottom = if self.borders & BORDER_BOTTOM != 0 { 1 } else { 0 };
        (top, bottom)
    }
    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        if area.is_empty() {
            return;
        }
        let border_style = Style::default();
        if self.borders & BORDER_TOP != 0 {
            for x in area.left()..area.right() {
                if let Some(c) = buf.cell_mut(x, area.top()) {
                    c.set_symbol("─").set_style(border_style);
                }
            }
        }
        if self.borders & BORDER_BOTTOM != 0 {
            let y = area.bottom() - 1;
            for x in area.left()..area.right() {
                if let Some(c) = buf.cell_mut(x, y) {
                    c.set_symbol("─").set_style(border_style);
                }
            }
        }
        // left aligned titles on the top row
        let mut titles_area = Rect { x: area.x, y: area.y, width: area.width, height: 1 };
        for title in &self.titles {
            if titles_area.is_empty() {
                break;
            }
            let title_width = title.width() as u16;
            let title_area = Rect { width: title_width.min(titles_area.width), ..titles_area };
            buf.set_style(title_area, Style::default());
            title.render(title_area, buf);
            titles_area.x = titles_area.x.saturating_add(title_width + 1);
            titles_area.width = titles_area.width.saturating_sub(title_width + 1);
        }
    }
}

// ---------------------------------------------------------------------------
// Line composers

pub struct WrappedLine<'a> {
    pub line: Vec<StyledGrapheme<'a>>,
    pub width: u16,
    pub alignment: Alignment,
}

/// Word wrapping, following the behavior of ratatui's WordWrapper.
pub fn word_wrap<'a>(
    input: Vec<(Vec<StyledGrapheme<'a>>, Alignment)>,
    max_line_width: u16,
    trim: bool,
) -> Vec<WrappedLine<'a>> {
    let mut out = Vec::new();
    if max_line_width == 0 {
        return out;
    }
    for (line_symbols, alignment) in input {
        let mut wrapped_lines: VecDeque<Vec<StyledGrapheme<'a>>> = VecDeque::new();
        let mut pending_line: Vec<StyledGrapheme<'a>> = Vec::new();
        let mut pending_word: Vec<StyledGrapheme<'a>> = Vec::new();
        let mut pending_whitespace: VecDeque<StyledGrapheme<'a>> = VecDeque::new();
        let mut line_width: u16 = 0;
        let mut word_width: u16 = 0;
        let mut whitespace_width: u16 = 0;
        let mut non_whitespace_previous = false;

        for grapheme in line_symbols {
            let is_whitespace = is_whitespace_grapheme(grapheme.symbol);
            let symbol_width = str_width(grapheme.symbol) as u16;

            if symbol_width > max_line_width {
                continue;
            }

            let word_found = non_whitespace_previous && is_whitespace;
            let trimmed_overflow = pending_line.is_empty() && trim && word_width + symbol_width > max_line_width;
            let whitespace_overflow =
                pending_line.is_empty() && trim && whitespace_width + symbol_width > max_line_width;
            let untrimmed_overflow = pending_line.is_empty()
                && !trim
                && word_width + whitespace_width + symbol_width > max_line_width;

            if word_found || trimmed_overflow || whitespace_overflow || untrimmed_overflow {
                if !pending_line.is_empty() || !trim {
                    pending_line.extend(pending_whitespace.drain(..));
                    line_width += whitespace_width;
                }
                pending_line.append(&mut pending_word);
                line_width += word_width;
                pending_whitespace.clear();
                whitespace_width = 0;
                word_width = 0;
            }

            let line_full = line_width >= max_line_width;
            let pending_word_overflow =
                symbol_width > 0 && line_width + whitespace_width + word_width >= max_line_width;

            if line_full || pending_word_overflow {
                let mut remaining_width = max_line_width.saturating_sub(line_width);
                wrapped_lines.push_back(std::mem::take(&mut pending_line));
                line_width = 0;

                while let Some(g) = pending_whitespace.front() {
                    let width = str_width(g.symbol) as u16;
                    if width > remaining_width {
                        break;
                    }
                    whitespace_width -= width;
                    remaining_width -= width;
                    pending_whitespace.pop_front();
                }

                if is_whitespace && pending_whitespace.is_empty() {
                    continue;
                }
            }

            if is_whitespace {
                whitespace_width += symbol_width;
                pending_whitespace.push_back(grapheme);
            } else {
                word_width += symbol_width;
                pending_word.push(grapheme);
            }

            non_whitespace_previous = !is_whitespace;
        }

        if pending_line.is_empty() && pending_word.is_empty() && !pending_whitespace.is_empty() {
            wrapped_lines.push_back(vec![]);
        }
        if !pending_line.is_empty() || !trim {
            pending_line.extend(pending_whitespace.drain(..));
        }
        pending_line.append(&mut pending_word);
        if !pending_line.is_empty() {
            wrapped_lines.push_back(pending_line);
        }
        if wrapped_lines.is_empty() {
            wrapped_lines.push_back(vec![]);
        }
        for line in wrapped_lines {
            let width = line.iter().map(|g| str_width(g.symbol) as u16).sum();
            out.push(WrappedLine { line, width, alignment });
        }
    }
    out
}

/// Line truncation (no wrapping), following ratatui's LineTruncator.
pub fn truncate_lines<'a>(
    input: Vec<(Vec<StyledGrapheme<'a>>, Alignment)>,
    max_line_width: u16,
) -> Vec<WrappedLine<'a>> {
    let mut out = Vec::new();
    if max_line_width == 0 {
        return out;
    }
    for (line, alignment) in input {
        let mut current = Vec::new();
        let mut width: u16 = 0;
        for g in line {
            let w = str_width(g.symbol) as u16;
            if w > max_line_width {
                continue;
            }
            if width + w > max_line_width {
                break;
            }
            width += w;
            current.push(g);
        }
        out.push(WrappedLine { line: current, width, alignment });
    }
    out
}

// ---------------------------------------------------------------------------
// Paragraph

#[derive(Clone, Debug)]
pub struct Paragraph {
    pub text: Text,
    pub block: Option<Block>,
    pub style: Style,
    pub wrap: Option<bool>,
    pub alignment: Alignment,
}

impl Paragraph {
    pub fn new(text: Text) -> Paragraph {
        Paragraph { text, block: None, style: Style::default(), wrap: None, alignment: Alignment::Left }
    }
    pub fn block(mut self, block: Block) -> Paragraph {
        self.block = Some(block);
        self
    }
    pub fn wrap(mut self, trim: bool) -> Paragraph {
        self.wrap = Some(trim);
        self
    }
    pub fn alignment(mut self, a: Alignment) -> Paragraph {
        self.alignment = a;
        self
    }

    fn styled_lines(&self) -> Vec<(Vec<StyledGrapheme<'_>>, Alignment)> {
        self.text
            .lines
            .iter()
            .map(|line| {
                let g = line.styled_graphemes(self.text.style);
                let a = line.alignment.or(self.text.alignment).unwrap_or(self.alignment);
                (g, a)
            })
            .collect()
    }

    /// Number of lines needed to render the paragraph at the given width (including the block).
    pub fn line_count(&self, width: u16) -> usize {
        if width < 1 {
            return 0;
        }
        let (top, bottom) = self.block.as_ref().map(|b| b.vertical_space()).unwrap_or((0, 0));
        let count = if let Some(trim) = self.wrap {
            word_wrap(self.styled_lines(), width, trim).len()
        } else {
            self.text.lines.len()
        };
        count + top as usize + bottom as usize
    }

    pub fn render(&self, area: Rect, buf: &mut Buffer) {
        let area = area.intersection(buf.area);
        buf.set_style(area, self.style);
        let mut text_area = area;
        if let Some(block) = &self.block {
            block.render(area, buf);
            text_area = block.inner(area);
        }
        if text_area.is_empty() {
            return;
        }
        buf.set_style(text_area, self.style);
        let lines = match self.wrap {
            Some(trim) => word_wrap(self.styled_lines(), text_area.width, trim),
            None => truncate_lines(self.styled_lines(), text_area.width),
        };
        for (y, wl) in lines.into_iter().enumerate() {
            if y as u16 >= text_area.height {
                break;
            }
            let mut x = line_offset(wl.width, text_area.width, wl.alignment);
            for g in wl.line {
                let width = str_width(g.symbol);
                if width == 0 {
                    continue;
                }
                let symbol = if g.symbol.is_empty() { " " } else { g.symbol };
                if let Some(c) = buf.cell_mut(text_area.left() + x, text_area.top() + y as u16) {
                    c.set_symbol(symbol).set_style(g.style);
                }
                x += width as u16;
            }
        }
    }
}

fn line_offset(line_width: u16, area_width: u16, alignment: Alignment) -> u16 {
    match alignment {
        Alignment::Center => (area_width / 2).saturating_sub(line_width / 2),
        Alignment::Right => area_width.saturating_sub(line_width),
        Alignment::Left => 0,
    }
}

// ---------------------------------------------------------------------------
// Table

