//! Layout splitting that mimics the constraint solver behavior of the
//! original application (lengths are honored when possible; when there is not
//! enough room the space is distributed so that neighboring segments are as
//! similar as possible).

use crate::buffer::Rect;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Constraint {
    Length(u16),
    Fill(u16),
}

/// Split `area` along one axis.
pub fn split(area: Rect, constraints: &[Constraint], spacing: u16, vertical: bool) -> Vec<Rect> {
    let (start, total) = if vertical { (area.y, area.height) } else { (area.x, area.width) };
    let sizes = solve(constraints, spacing as f64, total as f64);
    let mut rects = Vec::with_capacity(constraints.len());
    let mut pos = 0.0f64;
    for (i, s) in sizes.iter().enumerate() {
        let seg_start = pos;
        let seg_end = pos + s;
        let a = round(seg_start).max(0.0).min(total as f64) as u16;
        let b = round(seg_end).max(0.0).min(total as f64) as u16;
        let b = b.max(a);
        if vertical {
            rects.push(Rect { x: area.x, y: start + a, width: area.width, height: b - a });
        } else {
            rects.push(Rect { x: start + a, y: area.y, width: b - a, height: area.height });
        }
        pos = seg_end;
        if i + 1 < sizes.len() {
            pos += spacing as f64;
        }
    }
    rects
}

fn round(v: f64) -> f64 {
    (v + 1e-7).round()
}

fn solve(constraints: &[Constraint], spacing: f64, total: f64) -> Vec<f64> {
    let n = constraints.len();
    if n == 0 {
        return vec![];
    }
    let spacers = spacing * (n as f64 - 1.0);
    let fixed: f64 = constraints
        .iter()
        .map(|c| match c {
            Constraint::Length(l) => *l as f64,
            Constraint::Fill(_) => 0.0,
        })
        .sum::<f64>();
    let mut sizes = vec![0.0f64; n];
    if total >= fixed + spacers {
        let extra = total - fixed - spacers;
        let weight_sum: f64 = constraints
            .iter()
            .map(|c| match c {
                Constraint::Fill(w) => (*w as f64).max(1e-6),
                _ => 0.0,
            })
            .sum();
        for (i, c) in constraints.iter().enumerate() {
            sizes[i] = match c {
                Constraint::Length(l) => *l as f64,
                Constraint::Fill(w) => {
                    if weight_sum > 0.0 {
                        extra * (*w as f64).max(1e-6) / weight_sum
                    } else {
                        0.0
                    }
                }
            };
        }
        return sizes;
    }
    // Not enough room: fill segments collapse and the lengths share the deficit.
    let available = (total - spacers).max(0.0);
    let len_idx: Vec<usize> = (0..n).filter(|&i| matches!(constraints[i], Constraint::Length(_))).collect();
    if len_idx.is_empty() {
        return sizes;
    }
    let caps: Vec<f64> = len_idx
        .iter()
        .map(|&i| match constraints[i] {
            Constraint::Length(l) => l as f64,
            _ => 0.0,
        })
        .collect();
    let values = minimize_variation(constraints, &len_idx, &caps, available);
    for (k, &i) in len_idx.iter().enumerate() {
        sizes[i] = values[k];
    }
    sizes
}

/// Minimize the sum of absolute differences between neighbouring segments
/// (fill segments are fixed at zero) subject to box constraints and a fixed sum.
fn minimize_variation(constraints: &[Constraint], len_idx: &[usize], caps: &[f64], sum: f64) -> Vec<f64> {
    let n = constraints.len();
    let k = len_idx.len();
    // variable index of each segment (None for fills)
    let mut var_of = vec![None; n];
    for (v, &i) in len_idx.iter().enumerate() {
        var_of[i] = Some(v);
    }
    // Variables: s_0..s_{k-1}, then d_j for pairs where both are lengths.
    let mut pairs = Vec::new(); // (a, b) variable indices
    let mut lin_cost = vec![0.0f64; k];
    for j in 0..n.saturating_sub(1) {
        match (var_of[j], var_of[j + 1]) {
            (Some(a), Some(b)) => pairs.push((a, b)),
            (Some(a), None) => lin_cost[a] += 1.0,
            (None, Some(b)) => lin_cost[b] += 1.0,
            (None, None) => {}
        }
    }
    // tie breaking: earlier segments give up space first
    for (v, c) in lin_cost.iter_mut().enumerate() {
        *c += 1e-6 * (k - v) as f64;
    }
    let nv = k + pairs.len();
    let mut c = vec![0.0f64; nv];
    c[..k].copy_from_slice(&lin_cost);
    for p in 0..pairs.len() {
        c[k + p] = 1.0;
    }
    // Constraints as rows: (coeffs, kind, rhs) with kind: 0 '<=', 1 '>=', 2 '='
    let mut rows: Vec<(Vec<f64>, u8, f64)> = Vec::new();
    for v in 0..k {
        let mut r = vec![0.0; nv];
        r[v] = 1.0;
        rows.push((r, 0, caps[v]));
    }
    for (p, &(a, b)) in pairs.iter().enumerate() {
