        r1[k + p] = 1.0;
        r1[a] -= 1.0;
        r1[b] += 1.0;
        rows.push((r1, 1, 0.0));
        let mut r2 = vec![0.0; nv];
        r2[k + p] = 1.0;
        r2[a] += 1.0;
        r2[b] -= 1.0;
        rows.push((r2, 1, 0.0));
    }
    let mut r = vec![0.0; nv];
    for v in 0..k {
        r[v] = 1.0;
    }
    rows.push((r, 2, sum));
    match simplex(&c, &rows) {
        Some(x) => x[..k].to_vec(),
        None => {
            // fallback: proportional distribution
            let total_cap: f64 = caps.iter().sum();
            caps.iter().map(|cap| if total_cap > 0.0 { cap * sum / total_cap } else { 0.0 }).collect()
        }
    }
}

/// Minimize c^T x subject to rows, x >= 0. Two phase simplex with Bland's rule.
fn simplex(c: &[f64], rows: &[(Vec<f64>, u8, f64)]) -> Option<Vec<f64>> {
    const EPS: f64 = 1e-9;
    let nv = c.len();
    let m = rows.len();
    // Count slack and artificial variables.
    let mut n_slack = 0;
    for (_, kind, _) in rows {
        if *kind != 2 {
            n_slack += 1;
        }
    }
    let n_art = m;
    let ncols = nv + n_slack + n_art + 1; // last column = rhs
    let mut t = vec![vec![0.0f64; ncols]; m];
    let mut basis = vec![0usize; m];
    let mut slack_i = 0;
    for (i, (coef, kind, rhs)) in rows.iter().enumerate() {
        let mut coef = coef.clone();
        let mut rhs = *rhs;
        let mut slack_sign = match kind {
            0 => 1.0,
            1 => -1.0,
            _ => 0.0,
        };
        if rhs < 0.0 {
            for v in coef.iter_mut() {
                *v = -*v;
            }
            rhs = -rhs;
            slack_sign = -slack_sign;
        }
        t[i][..nv].copy_from_slice(&coef);
        if *kind != 2 {
            t[i][nv + slack_i] = slack_sign;
            slack_i += 1;
        }
        t[i][nv + n_slack + i] = 1.0;
        t[i][ncols - 1] = rhs;
        basis[i] = nv + n_slack + i;
    }
    // Phase 1: minimize sum of artificials.
    let mut cost1 = vec![0.0f64; ncols - 1];
    for a in 0..n_art {
        cost1[nv + n_slack + a] = 1.0;
    }
    if !run_simplex(&mut t, &mut basis, &cost1, ncols - 1, EPS) {
        return None;
    }
    // check feasibility
    let mut art_sum = 0.0;
    for (i, &b) in basis.iter().enumerate() {
        if b >= nv + n_slack {
            art_sum += t[i][ncols - 1];
        }
    }
    if art_sum > 1e-6 {
        return None;
    }
    // Drive artificials out of the basis where possible.
    for i in 0..m {
        if basis[i] >= nv + n_slack {
            if let Some(j) = (0..nv + n_slack).find(|&j| t[i][j].abs() > EPS) {
                pivot(&mut t, &mut basis, i, j);
            }
        }
    }
    // Phase 2: original objective, artificial columns disabled.
    let mut cost2 = vec![0.0f64; ncols - 1];
    cost2[..nv].copy_from_slice(c);
    let limit = nv + n_slack;
    if !run_simplex(&mut t, &mut basis, &cost2, limit, EPS) {
        return None;
    }
    let mut x = vec![0.0f64; nv];
    for (i, &b) in basis.iter().enumerate() {
        if b < nv {
            x[b] = t[i][ncols - 1];
        }
    }
    Some(x)
}

fn pivot(t: &mut [Vec<f64>], basis: &mut [usize], r: usize, col: usize) {
    let ncols = t[0].len();
    let p = t[r][col];
    for j in 0..ncols {
        t[r][j] /= p;
    }
    for i in 0..t.len() {
        if i != r {
            let f = t[i][col];
            if f != 0.0 {
                for j in 0..ncols {
                    t[i][j] -= f * t[r][j];
                }
            }
        }
    }
    basis[r] = col;
}

/// Run simplex iterations for the given cost vector, only allowing entering
/// columns below `limit`. Returns false if unbounded.
fn run_simplex(t: &mut [Vec<f64>], basis: &mut [usize], cost: &[f64], limit: usize, eps: f64) -> bool {
    let m = t.len();
    let ncols = t[0].len();
    for _iter in 0..10_000 {
        // reduced costs
        let mut entering = None;
        for j in 0..limit {
            if basis.contains(&j) {
                continue;
            }
            let mut rc = cost[j];
            for i in 0..m {
                rc -= cost[basis[i]] * t[i][j];
            }
            if rc < -eps {
                entering = Some(j);
                break; // Bland's rule
            }
        }
        let Some(col) = entering else {
            return true;
        };
        // ratio test
        let mut best: Option<(usize, f64)> = None;
        for i in 0..m {
            if t[i][col] > eps {
                let ratio = t[i][ncols - 1] / t[i][col];
                match best {
                    None => best = Some((i, ratio)),
                    Some((bi, br)) => {
                        if ratio < br - eps || ((ratio - br).abs() <= eps && basis[i] < basis[bi]) {
                            best = Some((i, ratio));
                        }
                    }
                }
            }
        }
        let Some((row, _)) = best else {
            return false;
        };
        pivot(t, basis, row, col);
    }
    true
}

