    Space,
    Upper,
    Word,
    Xdigit,
}

#[derive(Clone, Debug)]
enum ClassItem {
    Range(char, char),
    Perl(Perl, bool),
    Posix(Posix, bool),
    Nested(Box<Class>),
}

#[derive(Clone, Debug)]
struct Class {
    items: Vec<ClassItem>,
    negated: bool,
    case_insensitive: bool,
}

fn perl_matches(p: Perl, c: char) -> bool {
    match p {
        Perl::Digit => c.is_ascii_digit() || (!c.is_ascii() && c.is_numeric() && is_decimal_digit(c)),
        Perl::Word => is_word_char(c),
        Perl::Space => c.is_whitespace(),
    }
}

fn is_decimal_digit(c: char) -> bool {
    // Approximation of \p{Nd} for non-ASCII characters.
    let cp = c as u32;
    const RANGES: &[(u32, u32)] = &[
        (0x0660, 0x0669),
        (0x06F0, 0x06F9),
        (0x07C0, 0x07C9),
        (0x0966, 0x096F),
        (0x09E6, 0x09EF),
        (0x0A66, 0x0A6F),
        (0x0AE6, 0x0AEF),
        (0x0B66, 0x0B6F),
        (0x0BE6, 0x0BEF),
        (0x0C66, 0x0C6F),
        (0x0CE6, 0x0CEF),
        (0x0D66, 0x0D6F),
        (0x0DE6, 0x0DEF),
        (0x0E50, 0x0E59),
        (0x0ED0, 0x0ED9),
        (0x0F20, 0x0F29),
        (0x1040, 0x1049),
        (0x1090, 0x1099),
        (0x17E0, 0x17E9),
        (0x1810, 0x1819),
        (0xFF10, 0xFF19),
    ];
    RANGES.iter().any(|&(a, b)| cp >= a && cp <= b)
}

pub fn is_word_char(c: char) -> bool {
    if c.is_ascii() {
        return c.is_ascii_alphanumeric() || c == '_';
    }
    c.is_alphanumeric() || crate::unicode::char_width(c) == 0 && !c.is_control() || c == '\u{200C}' || c == '\u{200D}'
}

fn posix_matches(p: Posix, c: char) -> bool {
    match p {
        Posix::Alnum => c.is_ascii_alphanumeric(),
        Posix::Alpha => c.is_ascii_alphabetic(),
        Posix::Ascii => c.is_ascii(),
        Posix::Blank => c == ' ' || c == '\t',
        Posix::Cntrl => (c as u32) < 0x20 || c as u32 == 0x7F,
        Posix::Digit => c.is_ascii_digit(),
        Posix::Graph => (c as u32) >= 0x21 && (c as u32) <= 0x7E,
        Posix::Lower => c.is_ascii_lowercase(),
        Posix::Print => (c as u32) >= 0x20 && (c as u32) <= 0x7E,
        Posix::Punct => c.is_ascii_punctuation(),
        Posix::Space => matches!(c, ' ' | '\t' | '\n' | '\r' | '\x0B' | '\x0C'),
        Posix::Upper => c.is_ascii_uppercase(),
        Posix::Word => c.is_ascii_alphanumeric() || c == '_',
        Posix::Xdigit => c.is_ascii_hexdigit(),
    }
}

fn case_variants(c: char) -> Vec<char> {
    let mut v = Vec::new();
    let lower: Vec<char> = c.to_lowercase().collect();
    if lower.len() == 1 && lower[0] != c {
        v.push(lower[0]);
    }
    let upper: Vec<char> = c.to_uppercase().collect();
    if upper.len() == 1 && upper[0] != c {
        v.push(upper[0]);
    }
    // a few special simple case foldings
    match c {
        'k' | 'K' => v.push('\u{212A}'),
        '\u{212A}' => {
            v.push('k');
            v.push('K');
        }
        's' | 'S' => v.push('\u{17F}'),
        '\u{17F}' => {
            v.push('s');
            v.push('S');
        }
        _ => {}
    }
    v
}

impl Class {
    fn matches_raw(&self, c: char) -> bool {
        self.items.iter().any(|item| match item {
            ClassItem::Range(a, b) => c >= *a && c <= *b,
            ClassItem::Perl(p, neg) => perl_matches(*p, c) != *neg,
            ClassItem::Posix(p, neg) => posix_matches(*p, c) != *neg,
            ClassItem::Nested(cls) => cls.matches(c),
        })
    }
    fn matches(&self, c: char) -> bool {
        let mut m = self.matches_raw(c);
        if !m && self.case_insensitive {
            m = case_variants(c).into_iter().any(|v| self.matches_raw(v));
        }
        m != self.negated
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Assertion {
    StartLine,
    EndLine,
    StartText,
    EndText,
    WordBoundary,
    NotWordBoundary,
    WordStart,
    WordEnd,
}

#[derive(Clone, Debug)]
enum Node {
    Empty,
    Char(char, bool),
    Class(Class),
    Any(bool),
    Concat(Vec<Node>),
    Alt(Vec<Node>),
    Repeat { node: Box<Node>, min: u32, max: Option<u32>, greedy: bool },
    Assert(Assertion),
}

#[derive(Clone, Copy)]
struct Flags {
    i: bool,
    m: bool,
    s: bool,
    x: bool,
    u_swap: bool,
}

struct Parser<'a> {
    chars: Vec<char>,
    pos: usize,
    #[allow(dead_code)]
    src: &'a str,
}

fn err<T>(msg: &str) -> Result<T, Error> {
    Err(Error(msg.to_string()))
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn peek_at(&self, off: usize) -> Option<char> {
        self.chars.get(self.pos + off).copied()
    }
    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }
    fn eat(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    fn skip_ws(&mut self, flags: &Flags) {
        if !flags.x {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.pos += 1;
                }
                Some('#') => {
                    while let Some(c) = self.bump() {
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
    }

    /// Parse an alternation until ')' or end.
    fn parse_alt(&mut self, flags: &mut Flags, depth: usize) -> Result<Node, Error> {
        if depth > 250 {
            return err("nest limit exceeded");
        }
        let mut alts = Vec::new();
        let mut concat: Vec<Node> = Vec::new();
        loop {
            self.skip_ws(flags);
            let Some(c) = self.peek() else { break };
            match c {
                '|' => {
                    self.pos += 1;
                    alts.push(make_concat(std::mem::take(&mut concat)));
                }
                ')' => {
                    if depth == 0 {
                        return err("unopened group");
                    }
                    break;
                }
                '(' => {
                    self.pos += 1;
                    if let Some(node) = self.parse_group(flags, depth)? {
                        concat.push(node);
                    }
                }
                '*' | '+' | '?' => {
                    self.pos += 1;
                    let (min, max) = match c {
                        '*' => (0, None),
                        '+' => (1, None),
                        _ => (0, Some(1)),
                    };
                    self.apply_repeat(&mut concat, min, max, flags)?;
                }
                '{' => {
                    let save = self.pos;
                    self.pos += 1;
                    match self.parse_counted()? {
                        Some((min, max)) => self.apply_repeat(&mut concat, min, max, flags)?,
                        None => {
                            self.pos = save;
                            return err("invalid repetition");
                        }
                    }
                }
                '[' => {
                    self.pos += 1;
                    let cls = self.parse_class(flags)?;
                    concat.push(Node::Class(cls));
                }
                '.' => {
                    self.pos += 1;
                    concat.push(Node::Any(flags.s));
                }
                '^' => {
                    self.pos += 1;
                    concat.push(Node::Assert(if flags.m { Assertion::StartLine } else { Assertion::StartText }));
                }
                '$' => {
                    self.pos += 1;
                    concat.push(Node::Assert(if flags.m { Assertion::EndLine } else { Assertion::EndText }));
                }
                '\\' => {
                    self.pos += 1;
                    let node = self.parse_escape(flags)?;
                    concat.push(node);
                }
                _ => {
                    self.pos += 1;
                    concat.push(Node::Char(c, flags.i));
                }
            }
        }
        alts.push(make_concat(concat));
        if alts.len() == 1 {
            Ok(alts.pop().unwrap())
        } else {
            Ok(Node::Alt(alts))
        }
    }

    fn apply_repeat(&mut self, concat: &mut Vec<Node>, min: u32, max: Option<u32>, flags: &Flags) -> Result<(), Error> {
        let Some(last) = concat.pop() else {
            return err("repetition operator missing expression");
        };
        if let Node::Assert(_) = last {
            // repetition of an assertion is allowed in the regex crate; keep semantics simple
        }
        if let Node::Empty = last {
            return err("repetition operator missing expression");
        }
        let mut greedy = true;
        if self.eat('?') {
            greedy = false;
        }
        if flags.u_swap {
            greedy = !greedy;
        }
        if let Some(mx) = max {
            if mx < min {
                return err("invalid repetition range");
            }
        }
        if min > 1000 || max.map(|m| m > 1000).unwrap_or(false) {
            return err("repetition count too large");
        }
        concat.push(Node::Repeat { node: Box::new(last), min, max, greedy });
        Ok(())
    }

    /// Parses `n}`, `n,}` or `n,m}` after a '{'.
    fn parse_counted(&mut self) -> Result<Option<(u32, Option<u32>)>, Error> {
        let skip = |p: &mut Parser| {
            while p.peek().map(|c| c.is_whitespace()).unwrap_or(false) {
                p.pos += 1;
            }
        };
        skip(self);
        let min = self.parse_number();
        let Some(min) = min else {
            return Ok(None);
        };
        skip(self);
        if self.eat('}') {
            return Ok(Some((min, Some(min))));
        }
        if !self.eat(',') {
            return Ok(None);
        }
        skip(self);
        if self.eat('}') {
            return Ok(Some((min, None)));
        }
        let max = self.parse_number();
        let Some(max) = max else {
            return Ok(None);
        };
        skip(self);
        if !self.eat('}') {
            return Ok(None);
        }
        Ok(Some((min, Some(max))))
    }

    fn parse_number(&mut self) -> Option<u32> {
        let start = self.pos;
        let mut v: u64 = 0;
        while let Some(c) = self.peek() {
            if let Some(d) = c.to_digit(10) {
                v = v.saturating_mul(10).saturating_add(d as u64);
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.pos == start {
            None
        } else {
            Some(v.min(u32::MAX as u64) as u32)
        }
    }

    fn parse_group(&mut self, flags: &mut Flags, depth: usize) -> Result<Option<Node>, Error> {
        let mut inner_flags = *flags;
        if self.eat('?') {
            // named group
            if self.peek() == Some('P') && self.peek_at(1) == Some('<') {
                self.pos += 2;
                self.parse_group_name()?;
            } else if self.peek() == Some('<') {
                if matches!(self.peek_at(1), Some('=') | Some('!')) {
                    return err("look-around, including look-ahead and look-behind, is not supported");
                }
                self.pos += 1;
                self.parse_group_name()?;
            } else if matches!(self.peek(), Some('=') | Some('!')) {
                return err("look-around, including look-ahead and look-behind, is not supported");
            } else {
                // flags
                let mut negate = false;
                let mut any = false;
                loop {
                    let Some(c) = self.bump() else {
                        return err("unclosed group");
                    };
                    match c {
                        'i' => {
                            inner_flags.i = !negate;
                            any = true;
                        }
                        'm' => {
                            inner_flags.m = !negate;
                            any = true;
                        }
                        's' => {
                            inner_flags.s = !negate;
                            any = true;
                        }
                        'x' => {
                            inner_flags.x = !negate;
                            any = true;
                        }
                        'U' => {
                            inner_flags.u_swap = !negate;
                            any = true;
                        }
                        'u' | 'R' => {
                            any = true;
                        }
                        '-' => {
                            if negate {
                                return err("repeated negation");
                            }
                            negate = true;
                            any = false;
                        }
                        ':' => {
                            if negate && !any {
                                return err("expected flag after negation");
                            }
                            break;
                        }
                        ')' => {
                            if negate && !any {
                                return err("expected flag after negation");
                            }
                            // flags apply to the rest of the enclosing group
                            *flags = inner_flags;
                            return Ok(None);
                        }
                        _ => return err("unrecognized flag"),
                    }
                }
            }
        }
        let node = self.parse_alt(&mut inner_flags, depth + 1)?;
        if !self.eat(')') {
            return err("unclosed group");
        }
        Ok(Some(node))
    }

    fn parse_group_name(&mut self) -> Result<(), Error> {
        let start = self.pos;
        loop {
            match self.bump() {
                None => return err("unclosed capture group name"),
                Some('>') => break,
                Some(c) if c.is_alphanumeric() || c == '_' || c == '.' || c == '[' || c == ']' => {}
                Some(_) => return err("invalid capture group character"),
            }
        }
        if self.pos - 1 == start {
            return err("empty capture group name");
        }
        let first = self.chars[start];
        if first.is_ascii_digit() {
            return err("invalid capture group character");
        }
        Ok(())
    }

    fn parse_hex(&mut self, digits: usize) -> Result<char, Error> {
        let mut v: u32 = 0;
        for _ in 0..digits {
            let Some(c) = self.bump() else {
                return err("unexpected end of hex");
            };
            let Some(d) = c.to_digit(16) else {
                return err("invalid hexadecimal digit");
            };
            v = v * 16 + d;
        }
        char::from_u32(v).ok_or_else(|| Error("invalid Unicode scalar value".into()))
    }

    fn parse_hex_brace(&mut self) -> Result<char, Error> {
        let mut v: u32 = 0;
        let mut n = 0;
        loop {
            let Some(c) = self.bump() else {
                return err("unclosed hex");
            };
            if c == '}' {
                break;
            }
            let Some(d) = c.to_digit(16) else {
                return err("invalid hexadecimal digit");
            };
            v = v.saturating_mul(16).saturating_add(d);
            n += 1;
            if n > 8 {
                return err("invalid hex");
            }
        }
        if n == 0 {
            return err("empty hex");
        }
        char::from_u32(v).ok_or_else(|| Error("invalid Unicode scalar value".into()))
    }

    /// Parse an escape sequence that yields a literal char (used in classes).
    fn parse_escape_char(&mut self, c: char) -> Result<Option<char>, Error> {
        Ok(Some(match c {
            'n' => '\n',
            't' => '\t',
            'r' => '\r',
            'f' => '\x0C',
            'v' => '\x0B',
            'a' => '\x07',
            'x' => {
                if self.eat('{') {
                    self.parse_hex_brace()?
                } else {
                    self.parse_hex(2)?
                }
            }
            'u' => {
                if self.eat('{') {
                    self.parse_hex_brace()?
                } else {
                    self.parse_hex(4)?
                }
            }
            'U' => {
                if self.eat('{') {
                    self.parse_hex_brace()?
                } else {
                    self.parse_hex(8)?
                }
            }
            c if is_meta_escapable(c) => c,
            _ => return Ok(None),
        }))
    }

    fn parse_unicode_class(&mut self, negated: bool) -> Result<ClassItem, Error> {
        let name: String = if self.eat('{') {
            let mut s = String::new();
            loop {
                match self.bump() {
                    None => return err("unclosed unicode class"),
                    Some('}') => break,
                    Some(c) => s.push(c),
                }
            }
            s
        } else {
            match self.bump() {
                Some(c) => c.to_string(),
                None => return err("incomplete escape"),
            }
        };
        let (negated, name) = if let Some(rest) = name.strip_prefix('^') { (!negated, rest.to_string()) } else { (negated, name) };
        let key: String = name.chars().filter(|c| !c.is_whitespace() && *c != '_' && *c != '-').collect::<String>().to_lowercase();
        let cls = match key.as_str() {
            "l" | "letter" | "alphabetic" | "alpha" => Class { items: vec![ClassItem::Posix(Posix::Alpha, false)], negated: false, case_insensitive: false },
            _ => {
                let item = match key.as_str() {
                    "n" | "number" | "nd" | "digit" | "decimalnumber" => ClassItem::Perl(Perl::Digit, false),
                    "whitespace" | "space" | "z" => ClassItem::Perl(Perl::Space, false),
                    "lu" | "uppercaseletter" | "uppercase" | "upper" => ClassItem::Posix(Posix::Upper, false),
                    "ll" | "lowercaseletter" | "lowercase" | "lower" => ClassItem::Posix(Posix::Lower, false),
                    "p" | "punctuation" | "punct" => ClassItem::Posix(Posix::Punct, false),
                    "ascii" => ClassItem::Posix(Posix::Ascii, false),
                    "any" => ClassItem::Range('\0', char::MAX),
                    _ => return err("Unicode property not found"),
                };
                Class { items: vec![item], negated: false, case_insensitive: false }
            }
        };
        let cls = if key == "l" || key == "letter" || key == "alphabetic" || key == "alpha" {
            // Unicode letters
            Class { items: vec![ClassItem::Nested(Box::new(cls))], negated: false, case_insensitive: false }
        } else {
            cls
        };
        let mut cls = cls;
        if key == "l" || key == "letter" || key == "alphabetic" || key == "alpha" {
            cls = Class { items: vec![ClassItem::Perl(Perl::Word, false)], negated: false, case_insensitive: false };
            // approximate: alphabetic chars
            cls = Class {
                items: vec![ClassItem::Nested(Box::new(Class { items: cls.items, negated: false, case_insensitive: false }))],
                negated: false,
                case_insensitive: false,
            };
        }
        cls.negated = negated;
        Ok(ClassItem::Nested(Box::new(cls)))
    }

    fn parse_escape(&mut self, flags: &Flags) -> Result<Node, Error> {
        let Some(c) = self.bump() else {
            return err("incomplete escape sequence");
        };
        let node = match c {
            'd' => Node::Class(perl_class(Perl::Digit, false)),
            'D' => Node::Class(perl_class(Perl::Digit, true)),
            'w' => Node::Class(perl_class(Perl::Word, false)),
            'W' => Node::Class(perl_class(Perl::Word, true)),
            's' => Node::Class(perl_class(Perl::Space, false)),
            'S' => Node::Class(perl_class(Perl::Space, true)),
            'b' => {
                if self.peek() == Some('{') {
                    let save = self.pos;
                    self.pos += 1;
                    let mut name = String::new();
                    loop {
                        match self.bump() {
                            None => {
                                self.pos = save;
                                return err("unclosed word boundary");
                            }
                            Some('}') => break,
                            Some(c) => name.push(c),
                        }
                    }
                    match name.as_str() {
                        "start" => Node::Assert(Assertion::WordStart),
                        "end" => Node::Assert(Assertion::WordEnd),
                        "start-half" | "end-half" => Node::Assert(Assertion::WordBoundary),
                        _ => return err("unrecognized word boundary"),
                    }
                } else {
                    Node::Assert(Assertion::WordBoundary)
                }
            }
            'B' => Node::Assert(Assertion::NotWordBoundary),
            'A' => Node::Assert(Assertion::StartText),
            'z' => Node::Assert(Assertion::EndText),
            '<' => Node::Assert(Assertion::WordStart),
            '>' => Node::Assert(Assertion::WordEnd),
            'p' | 'P' => {
                let item = self.parse_unicode_class(c == 'P')?;
                Node::Class(Class { items: vec![item], negated: false, case_insensitive: false })
            }
            '1'..='9' => return err("backreferences are not supported"),
            _ => match self.parse_escape_char(c)? {
                Some(ch) => Node::Char(ch, flags.i),
                None => return err("unrecognized escape sequence"),
            },
        };
        Ok(node)
    }

    fn parse_class(&mut self, flags: &Flags) -> Result<Class, Error> {
        let mut cls = Class { items: Vec::new(), negated: false, case_insensitive: flags.i };
        if self.eat('^') {
            cls.negated = true;
        }
        let mut first = true;
        loop {
            let Some(c) = self.peek() else {
                return err("unclosed character class");
            };
            if c == ']' && !first {
                self.pos += 1;
                break;
            }
            first = false;
            // nested class or posix class
            if c == '[' {
                if self.peek_at(1) == Some(':') {
                    if let Some(item) = self.try_posix()? {
                        cls.items.push(item);
                        continue;
                    }
                }
                self.pos += 1;
                let nested = self.parse_class(flags)?;
                cls.items.push(ClassItem::Nested(Box::new(nested)));
                continue;
            }
            // set operations are treated as plain characters except '&&'
            if c == '&' && self.peek_at(1) == Some('&') {
                return err("unsupported class set operation");
            }
            let start = self.parse_class_atom()?;
            match start {
                ClassAtom::Item(item) => cls.items.push(item),
                ClassAtom::Char(a) => {
                    // range?
                    if self.peek() == Some('-') && self.peek_at(1).is_some() && self.peek_at(1) != Some(']') {
                        self.pos += 1;
                        let end = self.parse_class_atom()?;
                        match end {
                            ClassAtom::Char(b) => {
                                if b < a {
                                    return err("invalid character class range");
                                }
                                cls.items.push(ClassItem::Range(a, b));
                            }
                            ClassAtom::Item(_) => return err("invalid character class range"),
                        }
                    } else {
                        cls.items.push(ClassItem::Range(a, a));
                    }
                }
            }
        }
        Ok(cls)
    }

    fn try_posix(&mut self) -> Result<Option<ClassItem>, Error> {
        // at "[:"
        let save = self.pos;
        self.pos += 2;
        let negated = self.eat('^');
        let mut name = String::new();
        while let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() {
                name.push(c);
                self.pos += 1;
            } else {
                break;
            }
        }
        if self.peek() == Some(':') && self.peek_at(1) == Some(']') {
            self.pos += 2;
            let p = match name.as_str() {
                "alnum" => Posix::Alnum,
                "alpha" => Posix::Alpha,
                "ascii" => Posix::Ascii,
                "blank" => Posix::Blank,
                "cntrl" => Posix::Cntrl,
                "digit" => Posix::Digit,
                "graph" => Posix::Graph,
                "lower" => Posix::Lower,
                "print" => Posix::Print,
                "punct" => Posix::Punct,
                "space" => Posix::Space,
                "upper" => Posix::Upper,
                "word" => Posix::Word,
                "xdigit" => Posix::Xdigit,
                _ => return err("invalid ASCII class"),
            };
            return Ok(Some(ClassItem::Posix(p, negated)));
        }
        self.pos = save;
        Ok(None)
    }

    fn parse_class_atom(&mut self) -> Result<ClassAtom, Error> {
        let Some(c) = self.bump() else {
            return err("unclosed character class");
        };
        if c != '\\' {
            return Ok(ClassAtom::Char(c));
        }
        let Some(e) = self.bump() else {
            return err("incomplete escape sequence");
        };
        Ok(match e {
            'd' => ClassAtom::Item(ClassItem::Perl(Perl::Digit, false)),
            'D' => ClassAtom::Item(ClassItem::Perl(Perl::Digit, true)),
            'w' => ClassAtom::Item(ClassItem::Perl(Perl::Word, false)),
            'W' => ClassAtom::Item(ClassItem::Perl(Perl::Word, true)),
            's' => ClassAtom::Item(ClassItem::Perl(Perl::Space, false)),
            'S' => ClassAtom::Item(ClassItem::Perl(Perl::Space, true)),
            'p' | 'P' => ClassAtom::Item(self.parse_unicode_class(e == 'P')?),
            _ => match self.parse_escape_char(e)? {
                Some(ch) => ClassAtom::Char(ch),
                None => return err("unrecognized escape sequence"),
            },
        })
    }
}

enum ClassAtom {
    Char(char),
    Item(ClassItem),
}

fn is_meta_escapable(c: char) -> bool {
    // characters that may be escaped to produce themselves
    c.is_ascii_punctuation() || c == ' ' && false
}

fn perl_class(p: Perl, negated: bool) -> Class {
    Class { items: vec![ClassItem::Perl(p, false)], negated, case_insensitive: false }
}

fn make_concat(mut v: Vec<Node>) -> Node {
    match v.len() {
        0 => Node::Empty,
        1 => v.pop().unwrap(),
        _ => Node::Concat(v),
    }
}

// ---------------------------------------------------------------------------
// Compilation to a Pike VM program

#[derive(Clone, Debug)]
enum Inst {
    Char(char, bool),
    Class(usize),
    Any(bool),
    Split(usize, usize),
    Jmp(usize),
    Assert(Assertion),
    Match,
}

struct Compiler {
    insts: Vec<Inst>,
    classes: Vec<Class>,
}

impl Compiler {
    fn emit(&mut self, i: Inst) -> usize {
        self.insts.push(i);
        self.insts.len() - 1
    }
    fn compile(&mut self, node: &Node) -> Result<(), Error> {
        if self.insts.len() > 200_000 {
            return err("compiled regex exceeds size limit");
        }
        match node {
            Node::Empty => {}
            Node::Char(c, ci) => {
                self.emit(Inst::Char(*c, *ci));
            }
            Node::Class(cls) => {
                self.classes.push(cls.clone());
                let idx = self.classes.len() - 1;
                self.emit(Inst::Class(idx));
            }
            Node::Any(dotall) => {
                self.emit(Inst::Any(*dotall));
            }
            Node::Concat(v) => {
                for n in v {
                    self.compile(n)?;
                }
            }
            Node::Alt(v) => {
                let mut jumps = Vec::new();
                for (i, n) in v.iter().enumerate() {
                    if i + 1 < v.len() {
                        let split = self.emit(Inst::Split(0, 0));
                        let start = self.insts.len();
                        self.compile(n)?;
                        jumps.push(self.emit(Inst::Jmp(0)));
                        let next = self.insts.len();
                        self.insts[split] = Inst::Split(start, next);
                    } else {
                        self.compile(n)?;
                    }
                }
                let end = self.insts.len();
                for j in jumps {
                    self.insts[j] = Inst::Jmp(end);
                }
            }
            Node::Repeat { node, min, max, greedy } => {
                for _ in 0..*min {
                    self.compile(node)?;
                }
                match max {
                    None => {
                        // loop: L: split(body, exit); body; jmp L
                        let split = self.emit(Inst::Split(0, 0));
                        let body = self.insts.len();
                        self.compile(node)?;
                        self.emit(Inst::Jmp(split));
                        let exit = self.insts.len();
                        self.insts[split] = if *greedy { Inst::Split(body, exit) } else { Inst::Split(exit, body) };
                    }
                    Some(mx) => {
                        let mut splits = Vec::new();
                        for _ in *min..*mx {
                            let split = self.emit(Inst::Split(0, 0));
                            splits.push(split);
                            self.compile(node)?;
                        }
                        let exit = self.insts.len();
                        for s in splits {
                            let body = s + 1;
                            self.insts[s] = if *greedy { Inst::Split(body, exit) } else { Inst::Split(exit, body) };
                        }
                    }
                }
            }
            Node::Assert(a) => {
                self.emit(Inst::Assert(*a));
            }
        }
        Ok(())
    }
}

#[derive(Clone, Debug)]
pub struct Regex {
    insts: Vec<Inst>,
    classes: Vec<Class>,
}

impl Regex {
    pub fn new(pattern: &str) -> Result<Regex, Error> {
        let mut p = Parser { chars: pattern.chars().collect(), pos: 0, src: pattern };
        let mut flags = Flags { i: false, m: false, s: false, x: false, u_swap: false };
        let node = p.parse_alt(&mut flags, 0)?;
        if p.pos < p.chars.len() {
            return err("unopened group");
        }
        let mut c = Compiler { insts: Vec::new(), classes: Vec::new() };
        c.compile(&node)?;
        c.emit(Inst::Match);
        Ok(Regex { insts: c.insts, classes: c.classes })
    }

    pub fn is_match(&self, text: &str) -> bool {
        self.find_at(text, 0).is_some()
    }

    /// Find all non-overlapping matches (byte ranges).
    pub fn find_iter(&self, text: &str) -> Vec<(usize, usize)> {
        let mut out = Vec::new();
        let mut start = 0usize;
        let mut last_end: Option<usize> = None;
        while start <= text.len() {
            let Some((s, e)) = self.find_at(text, start) else { break };
            if s == e && Some(e) == last_end {
                // empty match right after the previous match: skip one char
                match text[e..].chars().next() {
                    Some(c) => {
                        start = e + c.len_utf8();
                        continue;
                    }
                    None => break,
                }
            }
            out.push((s, e));
            last_end = Some(e);
            if e > start {
                start = e;
            } else {
                match text[e..].chars().next() {
                    Some(c) => start = e + c.len_utf8(),
                    None => break,
                }
            }
        }
        out
    }

    fn check_assert(&self, a: Assertion, text: &str, pos: usize) -> bool {
        let prev = text[..pos].chars().next_back();
        let next = text[pos..].chars().next();
        match a {
            Assertion::StartText => pos == 0,
            Assertion::EndText => pos == text.len(),
            Assertion::StartLine => pos == 0 || prev == Some('\n'),
            Assertion::EndLine => pos == text.len() || next == Some('\n'),
            Assertion::WordBoundary | Assertion::NotWordBoundary | Assertion::WordStart | Assertion::WordEnd => {
                let pw = prev.map(is_word_char).unwrap_or(false);
                let nw = next.map(is_word_char).unwrap_or(false);
                match a {
                    Assertion::WordBoundary => pw != nw,
                    Assertion::NotWordBoundary => pw == nw,
                    Assertion::WordStart => !pw && nw,
                    _ => pw && !nw,
                }
            }
        }
    }

    fn add_thread(&self, list: &mut Vec<(usize, usize)>, seen: &mut [bool], pc: usize, start: usize, text: &str, pos: usize) {
        // iterative DFS preserving priority order
        let mut stack = vec![pc];
        while let Some(pc) = stack.pop() {
            if seen[pc] {
                continue;
            }
            seen[pc] = true;
            match &self.insts[pc] {
                Inst::Jmp(t) => stack.push(*t),
                Inst::Split(a, b) => {
                    stack.push(*b);
                    stack.push(*a);
                }
                Inst::Assert(a) => {
                    if self.check_assert(*a, text, pos) {
                        stack.push(pc + 1);
                    }
                }
                _ => list.push((pc, start)),
            }
        }
    }

    fn char_matches(&self, inst: &Inst, c: char) -> bool {
        match inst {
            Inst::Char(x, ci) => {
                if *x == c {
                    true
                } else if *ci {
                    case_variants(c).contains(x)
                } else {
                    false
                }
            }
            Inst::Class(idx) => self.classes[*idx].matches(c),
            Inst::Any(dotall) => *dotall || c != '\n',
            _ => false,
        }
    }

    /// Leftmost-first search starting at byte offset `from`.
    pub fn find_at(&self, text: &str, from: usize) -> Option<(usize, usize)> {
        let n = self.insts.len();
        let mut clist: Vec<(usize, usize)> = Vec::new();
        let mut nlist: Vec<(usize, usize)> = Vec::new();
        let mut seen = vec![false; n];
        let mut matched: Option<(usize, usize)> = None;
        let mut pos = from;
        loop {
            if matched.is_none() {
                // start a new thread at this position (lowest priority)
                self.add_thread(&mut clist, &mut seen, 0, pos, text, pos);
            }
            if clist.is_empty() {
                break;
            }
            let c = text[pos..].chars().next();
            for s in seen.iter_mut() {
                *s = false;
            }
            let next_pos = pos + c.map(|c| c.len_utf8()).unwrap_or(0);
            let mut i = 0;
            while i < clist.len() {
                let (pc, start) = clist[i];
                match &self.insts[pc] {
                    Inst::Match => {
                        matched = Some((start, pos));
                        // cut lower priority threads
                        break;
                    }
                    inst => {
                        if let Some(ch) = c {
                            if self.char_matches(inst, ch) {
                                self.add_thread(&mut nlist, &mut seen, pc + 1, start, text, next_pos);
                            }
                        }
                    }
                }
                i += 1;
            }
            std::mem::swap(&mut clist, &mut nlist);
            nlist.clear();
            for s in seen.iter_mut() {
                *s = false;
            }
            if c.is_none() {
                // process remaining threads at end of input for matches
                if !clist.is_empty() {
                    // threads in clist were added at next_pos == pos (no char); they can't advance
                }
                break;
            }
            pos = next_pos;
            if clist.is_empty() && matched.is_some() {
                break;
            }
        }
        // threads remaining at the end of text may contain a Match
        if matched.is_none() || !clist.is_empty() {
            for &(pc, start) in &clist {
                if let Inst::Match = self.insts[pc] {
                    let cand = (start, pos);
                    match matched {
                        None => matched = Some(cand),
                        Some(_) => matched = Some(cand),
                    }
                    break;
                }
            }
        }
        matched
    }
}

/// Escape all regex meta characters.
pub fn escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if matches!(
            c,
            '\\' | '.' | '+' | '*' | '?' | '(' | ')' | '|' | '[' | ']' | '{' | '}' | '^' | '$' | '#' | '&' | '-' | '~'
        ) {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn f(p: &str, t: &str) -> Vec<(usize, usize)> {
        Regex::new(p).unwrap().find_iter(t)
    }

    #[test]
    fn basics() {
        assert_eq!(f("a", "banana"), vec![(1, 2), (3, 4), (5, 6)]);
        assert_eq!(f("an", "banana"), vec![(1, 3), (3, 5)]);
        assert_eq!(f("a*", "baa"), vec![(0, 0), (1, 3)]);
        assert_eq!(f("^", "abc"), vec![(0, 0)]);
        assert_eq!(f("z|y", "xyz"), vec![(1, 2), (2, 3)]);
        assert_eq!(f("def|j", "abcdefghij"), vec![(3, 6), (9, 10)]);
        assert!(Regex::new("^foo\\.bar$").unwrap().is_match("foo.bar"));
        assert!(!Regex::new("^foo\\.bar$").unwrap().is_match("fooxbar"));
        assert!(Regex::new("(").is_err());
        assert!(Regex::new(")").is_err());
        assert!(Regex::new("[").is_err());
        assert!(Regex::new("*").is_err());
        assert!(Regex::new("a{2,1}").is_err());
        assert_eq!(f("a+?", "aaa"), vec![(0, 1), (1, 2), (2, 3)]);
        assert_eq!(f("(?i)AB", "xaBy"), vec![(1, 3)]);
        assert_eq!(f("[a-c]+", "xxabcabx"), vec![(2, 7)]);
        assert_eq!(f("\\d+", "a12b3"), vec![(1, 3), (4, 5)]);
        assert_eq!(f("a|ab", "ab"), vec![(0, 1)]);
        assert_eq!(f("ab|a", "ab"), vec![(0, 2)]);
        assert_eq!(f("\\bfoo\\b", "foo foobar foo"), vec![(0, 3), (11, 14)]);
        assert_eq!(f("x*", ""), vec![(0, 0)]);
        assert!(Regex::new("^$").unwrap().is_match(""));
        assert!(!Regex::new("^$").unwrap().is_match("all"));
        assert!(Regex::new("^$|xyz").unwrap().is_match(""));
        assert_eq!(escape("foo.bar"), "foo\\.bar");
    }
}
