//! Single line text input with emacs-like editing (cursor in chars).

use crate::input::{Key, KeyCode, ALT, CONTROL, NONE, SHIFT};

#[derive(Debug, Clone, Default)]
pub struct TextInput {
    pub value: String,
    pub cursor: usize,
}

impl TextInput {
    fn len(&self) -> usize {
        self.value.chars().count()
    }

    pub fn handle(&mut self, key: &Key) {
        use KeyCode::*;
        let m = key.modifiers;
        match (&key.code, m) {
            (Backspace, NONE) => self.delete_prev_char(),
            (Char('h'), CONTROL) => self.delete_prev_char(),
            (Delete, NONE) => self.delete_next_char(),
            (Tab, NONE) => {}
            (Left, NONE) | (Char('b'), CONTROL) => {
                if self.cursor > 0 {
                    self.cursor -= 1;
                }
            }
            (Left, CONTROL) => self.prev_word(),
            (Right, NONE) | (Char('f'), CONTROL) => {
                if self.cursor < self.len() {
                    self.cursor += 1;
                }
            }
            (Right, CONTROL) => self.next_word(),
            (Char('u'), CONTROL) => {
                self.value.clear();
                self.cursor = 0;
            }
            (Char('w'), CONTROL) | (Backspace, ALT) => self.delete_prev_word(),
            (Delete, CONTROL) => self.delete_next_word(),
            (Char('k'), CONTROL) => {
                self.value = self.value.chars().take(self.cursor).collect();
            }
            (Char('a'), CONTROL) | (Home, NONE) => self.cursor = 0,
            (Char('e'), CONTROL) | (End, NONE) => self.cursor = self.len(),
            (Char(c), NONE) | (Char(c), SHIFT) => self.insert(*c),
            _ => {}
        }
    }

    fn insert(&mut self, c: char) {
        if self.cursor == self.len() {
            self.value.push(c);
        } else {
            self.value = self
                .value
                .chars()
                .take(self.cursor)
                .chain(std::iter::once(c))
                .chain(self.value.chars().skip(self.cursor))
                .collect();
        }
        self.cursor += 1;
    }

    fn delete_prev_char(&mut self) {
        if self.cursor == 0 {
            return;
        }
        self.cursor -= 1;
        let cur = self.cursor;
        self.value = self.value.chars().enumerate().filter(|(i, _)| *i != cur).map(|(_, c)| c).collect();
    }

    fn delete_next_char(&mut self) {
        if self.cursor == self.len() {
            return;
        }
        let cur = self.cursor;
        self.value = self.value.chars().enumerate().filter(|(i, _)| *i != cur).map(|(_, c)| c).collect();
    }

    fn prev_word(&mut self) {
        if self.cursor == 0 {
            return;
        }
        let n = self.len();
        self.cursor = self
            .value
            .chars()
            .rev()
            .skip(n.max(self.cursor) - self.cursor)
            .skip_while(|c| !c.is_alphanumeric())
            .skip_while(|c| c.is_alphanumeric())
            .count();
    }

    fn next_word(&mut self) {
        let n = self.len();
        if self.cursor == n {
            return;
        }
        self.cursor = self
            .value
            .chars()
