//! Flamegraph data model built from folded stacks.

use std::collections::HashMap;
use std::hash::{DefaultHasher, Hash, Hasher};

use crate::regex::Regex;

pub const ROOT: usize = 0;

#[derive(Debug, Clone)]
pub struct Stack {
    /// Frame name ("" for the root).
    pub short_name: String,
    /// Full stack path ("all" for the root), used for coloring.
    pub full_name: String,
    pub total: u64,
    pub self_count: u64,
    pub parent: Option<usize>,
    pub children: Vec<usize>,
    pub level: usize,
    pub hit: bool,
}

impl Stack {
    pub fn display_name(&self) -> &str {
        if self.parent.is_none() {
            "all"
        } else {
            &self.short_name
        }
    }
}

#[derive(Debug, Clone)]
pub struct TopEntry {
    pub name: String,
    pub total: u64,
    pub own: u64,
}

#[derive(Debug, Clone)]
pub struct SearchPattern {
    pub pattern: String,
    pub re: Regex,
}

pub struct FlameGraph {
    pub stacks: Vec<Stack>,
    lookup: Vec<HashMap<String, usize>>,
    pub top: Vec<TopEntry>,
    pub hit_total: u64,
}

impl FlameGraph {
    pub fn from_string(data: &str, sorted: bool) -> FlameGraph {
        let root = Stack {
            short_name: String::new(),
            full_name: "all".to_string(),
            total: 0,
            self_count: 0,
            parent: None,
            children: Vec::new(),
            level: 0,
            hit: false,
        };
        let mut fg = FlameGraph { stacks: vec![root], lookup: vec![HashMap::new()], top: Vec::new(), hit_total: 0 };
        for line in data.split('\n') {
            let Some((stack, count)) = line.rsplit_once(' ') else {
                continue;
            };
            let Ok(count) = count.parse::<u64>() else {
                continue;
            };
            fg.add_stack(stack, count);
        }
        if sorted {
            fg.sort_children(ROOT);
        }
        fg.compute_top();
        fg
    }

    fn add_stack(&mut self, stack: &str, count: u64) {
        let mut node = ROOT;
        self.stacks[ROOT].total = self.stacks[ROOT].total.wrapping_add(count);
        let mut full = String::new();
        for (i, frame) in stack.split(';').enumerate() {
            if i > 0 {
                full.push(';');
            }
            full.push_str(frame);
            let next = match self.lookup[node].get(frame) {
                Some(&id) => id,
                None => {
                    let id = self.stacks.len();
                    let level = self.stacks[node].level + 1;
                    self.stacks.push(Stack {
                        short_name: frame.to_string(),
                        full_name: full.clone(),
                        total: 0,
                        self_count: 0,
                        parent: Some(node),
                        children: Vec::new(),
                        level,
                        hit: false,
                    });
                    self.lookup.push(HashMap::new());
                    self.lookup[node].insert(frame.to_string(), id);
                    self.stacks[node].children.push(id);
                    id
                }
            };
            node = next;
            self.stacks[node].total = self.stacks[node].total.wrapping_add(count);
        }
        self.stacks[node].self_count = self.stacks[node].self_count.wrapping_add(count);
    }

    fn sort_children(&mut self, node: usize) {
        let mut children = std::mem::take(&mut self.stacks[node].children);
        children.sort_by_key(|&c| self.stacks[c].total);
        children.reverse();
        for &c in &children {
            self.sort_children(c);
        }
        self.stacks[node].children = children;
    }

    fn compute_top(&mut self) {
        let mut map: HashMap<String, (u64, u64)> = HashMap::new();
        let mut order: Vec<String> = Vec::new();
        // iterative DFS keeping track of names on the current path
        let mut path_names: HashMap<String, usize> = HashMap::new();
        enum Step {
            Enter(usize),
            Leave(usize),
        }
        let mut stack = vec![];
        for &c in self.stacks[ROOT].children.iter().rev() {
            stack.push(Step::Enter(c));
        }
        while let Some(step) = stack.pop() {
            match step {
                Step::Enter(id) => {
                    let s = &self.stacks[id];
                    let name = s.short_name.clone();
                    let on_path = path_names.get(&name).copied().unwrap_or(0) > 0;
                    let entry = map.entry(name.clone()).or_insert_with(|| {
                        order.push(name.clone());
                        (0, 0)
                    });
                    if !on_path {
                        entry.0 = entry.0.wrapping_add(s.total);
                    }
                    entry.1 = entry.1.wrapping_add(s.self_count);
                    *path_names.entry(name).or_insert(0) += 1;
                    stack.push(Step::Leave(id));
                    for &c in s.children.iter().rev() {
                        stack.push(Step::Enter(c));
                    }
                }
                Step::Leave(id) => {
                    let name = &self.stacks[id].short_name;
                    if let Some(v) = path_names.get_mut(name) {
                        *v -= 1;
                    }
                }
            }
        }
        self.top = order
            .into_iter()
            .map(|name| {
                let (total, own) = map[&name];
                TopEntry { name, total, own }
            })
            .collect();
    }

    pub fn root_total(&self) -> u64 {
        self.stacks[ROOT].total
    }

    /// Update hit flags for the given pattern (or clear them).
    pub fn set_search(&mut self, pattern: Option<&SearchPattern>) {
        for s in self.stacks.iter_mut() {
            s.hit = match pattern {
                Some(p) => p.re.is_match(&s.short_name),
                None => false,
            };
        }
        // total samples of hit frames without hit ancestors
        let mut total: u64 = 0;
        if pattern.is_some() {
            let mut stack = vec![ROOT];
            while let Some(id) = stack.pop() {
                let s = &self.stacks[id];
                if s.hit {
                    total = total.wrapping_add(s.total);
                } else {
                    stack.extend(s.children.iter().copied());
                }
            }
        }
        self.hit_total = total;
    }

    pub fn is_ancestor_or_self(&self, ancestor: usize, mut node: usize) -> bool {
        loop {
            if node == ancestor {
                return true;
            }
            match self.stacks[node].parent {
                Some(p) => node = p,
                None => return false,
            }
        }
    }
}

/// Hash based color for a stack (inferno "hot" palette).
pub fn stack_color(full_name: &str) -> (u8, u8, u8) {
    let mut hasher = DefaultHasher::new();
    full_name.hash(&mut hasher);
    let v = hasher.finish() as f64 / u64::MAX as f64;
    let r = 205u8.wrapping_add((50.0 * v) as u8);
    let g = (230.0 * v) as u8;
    let b = (55.0 * v) as u8;
    (r, g, b)
}

pub fn dim((r, g, b): (u8, u8, u8)) -> (u8, u8, u8) {
    ((r as f64 * 0.4) as u8, (g as f64 * 0.4) as u8, (b as f64 * 0.4) as u8)
}

pub fn text_color((r, g, b): (u8, u8, u8)) -> (u8, u8, u8) {
    let lum = 0.2126 * r as f64 + 0.7152 * g as f64 + 0.0722 * b as f64;
    if lum > 128.0 {
        (10, 10, 10)
    } else {
        (225, 225, 225)
    }
}
EOF
