                        b'P' => KeyCode::F(1),
                        b'Q' => KeyCode::F(2),
                        b'R' => KeyCode::F(3),
                        _ => KeyCode::F(4),
                    };
                    key(code, m, n)
                }
                b'M' | b'm' | b'R' | b'c' | b'n' | b't' => Parse::Done(Event::Other, n),
                _ => Parse::Invalid,
            }
