//! Terminal input decoding (escape sequences to key events).

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum KeyCode {
    Char(char),
    Enter,
    Tab,
    BackTab,
    Backspace,
    Esc,
    Left,
    Right,
    Up,
    Down,
    Home,
    End,
    PageUp,
    PageDown,
    Insert,
    Delete,
    F(u8),
    Null,
}

pub type Modifiers = u8;
pub const NONE: Modifiers = 0;
pub const SHIFT: Modifiers = 1;
pub const CONTROL: Modifiers = 2;
pub const ALT: Modifiers = 4;
pub const SUPER: Modifiers = 8;
pub const HYPER: Modifiers = 16;
pub const META: Modifiers = 32;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Key {
    pub code: KeyCode,
    pub modifiers: Modifiers,
}

impl Key {
    fn new(code: KeyCode, modifiers: Modifiers) -> Key {
        Key { code, modifiers }
    }
}

#[derive(Debug)]
pub enum Event {
    Key(Key),
    Other,
}

enum Parse {
    /// Need more bytes to decide.
    Incomplete,
    /// Could not parse; discard the buffer.
    Invalid,
    /// Parsed an event consuming the given number of bytes.
    Done(Event, usize),
}

/// Decode as many events as possible from `buf`. Remaining incomplete bytes
/// are kept in `buf`. `more_available` tells whether more input is pending.
pub fn decode(buf: &mut Vec<u8>, more_available: bool) -> Vec<Event> {
    let mut events = Vec::new();
    let mut start = 0;
    while start < buf.len() {
        let rest = &buf[start..];
        let avail = more_available || false;
        match parse_event(rest, avail || start + 1 < buf.len() && rest.len() > 1) {
            Parse::Done(ev, n) => {
                events.push(ev);
                start += n;
            }
            Parse::Invalid => {
                start = buf.len();
            }
            Parse::Incomplete => {
                if more_available {
                    break;
                }
                // Nothing more is coming: interpret a lone ESC as Esc.
                if rest[0] == 0x1B {
                    events.push(Event::Key(Key::new(KeyCode::Esc, NONE)));
                    start += 1;
                } else {
                    start = buf.len();
                }
            }
        }
    }
    buf.drain(..start);
    events
}

fn parse_event(buf: &[u8], _input_available: bool) -> Parse {
    if buf.is_empty() {
        return Parse::Incomplete;
    }
    match buf[0] {
        0x1B => {
            if buf.len() == 1 {
                return Parse::Done(Event::Key(Key::new(KeyCode::Esc, NONE)), 1);
            }
            match buf[1] {
                b'O' => {
                    if buf.len() == 2 {
                        return Parse::Incomplete;
                    }
                    let code = match buf[2] {
                        b'D' => KeyCode::Left,
                        b'C' => KeyCode::Right,
                        b'A' => KeyCode::Up,
                        b'B' => KeyCode::Down,
                        b'H' => KeyCode::Home,
                        b'F' => KeyCode::End,
                        v @ b'P'..=b'S' => KeyCode::F(1 + v - b'P'),
                        _ => return Parse::Invalid,
                    };
                    Parse::Done(Event::Key(Key::new(code, NONE)), 3)
                }
                b'[' => parse_csi(buf),
                0x1B => Parse::Done(Event::Key(Key::new(KeyCode::Esc, NONE)), 2),
                _ => match parse_event(&buf[1..], false) {
                    Parse::Done(Event::Key(mut k), n) => {
                        k.modifiers |= ALT;
                        Parse::Done(Event::Key(k), n + 1)
                    }
                    Parse::Done(e, n) => Parse::Done(e, n + 1),
                    other => other,
                },
            }
        }
        b'\r' => Parse::Done(Event::Key(Key::new(KeyCode::Enter, NONE)), 1),
        b'\t' => Parse::Done(Event::Key(Key::new(KeyCode::Tab, NONE)), 1),
        0x7F => Parse::Done(Event::Key(Key::new(KeyCode::Backspace, NONE)), 1),
        c @ 0x01..=0x1A => {
            Parse::Done(Event::Key(Key::new(KeyCode::Char((c - 0x1 + b'a') as char), CONTROL)), 1)
        }
        c @ 0x1C..=0x1F => {
            Parse::Done(Event::Key(Key::new(KeyCode::Char((c - 0x1C + b'4') as char), CONTROL)), 1)
        }
        0x00 => Parse::Done(Event::Key(Key::new(KeyCode::Char(' '), CONTROL)), 1),
        _ => parse_utf8_char(buf),
    }
}

fn parse_utf8_char(buf: &[u8]) -> Parse {
    let first = buf[0];
    let len = if first < 0x80 {
        1
    } else if first & 0xE0 == 0xC0 {
        2
    } else if first & 0xF0 == 0xE0 {
        3
    } else if first & 0xF8 == 0xF0 {
        4
    } else {
        return Parse::Invalid;
    };
    if buf.len() < len {
        return Parse::Incomplete;
    }
    match std::str::from_utf8(&buf[..len]) {
        Ok(s) => {
            let c = s.chars().next().unwrap();
            let m = if c.is_uppercase() { SHIFT } else { NONE };
            Parse::Done(Event::Key(Key::new(KeyCode::Char(c), m)), len)
        }
        Err(_) => Parse::Invalid,
    }
}

fn parse_modifiers(mask: u8) -> Modifiers {
    let m = mask.saturating_sub(1);
    let mut r = NONE;
    if m & 1 != 0 {
        r |= SHIFT;
    }
    if m & 2 != 0 {
        r |= ALT;
    }
    if m & 4 != 0 {
        r |= CONTROL;
    }
    if m & 8 != 0 {
        r |= SUPER;
    }
    if m & 16 != 0 {
        r |= HYPER;
    }
    if m & 32 != 0 {
        r |= META;
    }
    r
}

fn parse_csi(buf: &[u8]) -> Parse {
    if buf.len() == 2 {
        return Parse::Incomplete;
    }
    let key = |code: KeyCode, m: Modifiers, n: usize| Parse::Done(Event::Key(Key::new(code, m)), n);
    match buf[2] {
        b'[' => {
            if buf.len() == 3 {
                return Parse::Incomplete;
            }
            match buf[3] {
                v @ b'A'..=b'E' => key(KeyCode::F(1 + v - b'A'), NONE, 4),
                _ => Parse::Invalid,
            }
        }
        b'D' => key(KeyCode::Left, NONE, 3),
        b'C' => key(KeyCode::Right, NONE, 3),
        b'A' => key(KeyCode::Up, NONE, 3),
        b'B' => key(KeyCode::Down, NONE, 3),
        b'H' => key(KeyCode::Home, NONE, 3),
        b'F' => key(KeyCode::End, NONE, 3),
        b'Z' => key(KeyCode::BackTab, SHIFT, 3),
        b'M' => {
            // X10 mouse: ESC [ M Cb Cx Cy
            if buf.len() < 6 {
                Parse::Incomplete
            } else {
                Parse::Done(Event::Other, 6)
            }
        }
        b'<' => {
            // SGR mouse
            match buf.iter().position(|&b| b == b'M' || b == b'm') {
                Some(p) => Parse::Done(Event::Other, p + 1),
                None => Parse::Incomplete,
            }
        }
        b'I' | b'O' => Parse::Done(Event::Other, 3),
        b'P' => key(KeyCode::F(1), NONE, 3),
        b'Q' => key(KeyCode::F(2), NONE, 3),
        b'S' => key(KeyCode::F(4), NONE, 3),
        b'?' => match buf.last() {
            Some(b'u') | Some(b'c') => Parse::Done(Event::Other, buf.len()),
            _ => {
                if buf.len() > 32 {
                    Parse::Invalid
                } else {
                    Parse::Incomplete
                }
            }
        },
        b'0'..=b'9' => {
            // find the final byte
            let mut end = None;
            for (i, &b) in buf.iter().enumerate().skip(2) {
                if (0x40..=0x7E).contains(&b) {
                    end = Some(i);
                    break;
                }
            }
            let Some(end) = end else {
                return if buf.len() > 64 { Parse::Invalid } else { Parse::Incomplete };
            };
            let params = &buf[2..end];
            let final_byte = buf[end];
            let n = end + 1;
            let s = match std::str::from_utf8(params) {
                Ok(s) => s,
                Err(_) => return Parse::Invalid,
            };
            let parts: Vec<&str> = s.split(';').collect();
            match final_byte {
                b'~' => {
                    let first: u16 = parts[0].split(':').next().unwrap_or("").parse().unwrap_or(0);
                    let m = parts
                        .get(1)
                        .and_then(|p| p.split(':').next())
                        .and_then(|p| p.parse::<u8>().ok())
                        .map(parse_modifiers)
                        .unwrap_or(NONE);
                    let code = match first {
                        1 | 7 => KeyCode::Home,
                        2 => KeyCode::Insert,
                        3 => KeyCode::Delete,
                        4 | 8 => KeyCode::End,
                        5 => KeyCode::PageUp,
                        6 => KeyCode::PageDown,
                        v @ 11..=15 => KeyCode::F((v - 10) as u8),
                        v @ 17..=21 => KeyCode::F((v - 11) as u8),
                        v @ 23..=26 => KeyCode::F((v - 12) as u8),
                        v @ 28..=29 => KeyCode::F((v - 15) as u8),
                        v @ 31..=34 => KeyCode::F((v - 17) as u8),
                        200 | 201 => return Parse::Done(Event::Other, n),
                        _ => return Parse::Invalid,
                    };
                    key(code, m, n)
                }
                b'u' => {
                    // kitty keyboard protocol
                    let cp: u32 = parts[0].split(':').next().unwrap_or("").parse().unwrap_or(0);
                    let m = parts
                        .get(1)
                        .and_then(|p| p.split(':').next())
                        .and_then(|p| p.parse::<u8>().ok())
                        .map(parse_modifiers)
                        .unwrap_or(NONE);
                    let code = match cp {
                        0x1B => KeyCode::Esc,
                        0x0D => KeyCode::Enter,
                        0x09 => KeyCode::Tab,
                        0x7F => KeyCode::Backspace,
                        _ => match char::from_u32(cp) {
                            Some(c) => KeyCode::Char(c),
                            None => return Parse::Invalid,
                        },
                    };
                    key(code, m, n)
                }
                b'A' | b'B' | b'C' | b'D' | b'F' | b'H' | b'P' | b'Q' | b'R' | b'S' => {
                    let m = parts
                        .get(1)
                        .and_then(|p| p.split(':').next())
                        .and_then(|p| p.parse::<u8>().ok())
                        .map(parse_modifiers)
                        .unwrap_or(NONE);
                    let code = match final_byte {
                        b'A' => KeyCode::Up,
                        b'B' => KeyCode::Down,
                        b'C' => KeyCode::Right,
                        b'D' => KeyCode::Left,
                        b'F' => KeyCode::End,
                        b'H' => KeyCode::Home,
                        b'P' => KeyCode::F(1),
                        b'Q' => KeyCode::F(2),
                        b'R' => KeyCode::F(3),
                        _ => KeyCode::F(4),
                    };
                    key(code, m, n)
                }
                b'M' | b'm' | b'R' | b'c' | b'n' | b't' => Parse::Done(Event::Other, n),
                _ => Parse::Invalid,
            }
        }
        _ => Parse::Invalid,
    }
}
