//! Low level terminal handling: raw mode, size queries and output.

use std::fs::{File, OpenOptions};
use std::io::{self, Write};
use std::os::unix::io::{AsRawFd, IntoRawFd, RawFd};

use crate::buffer::{Buffer, Cell, Color, BOLD, CROSSED_OUT, DIM, ITALIC, RAPID_BLINK, REVERSED, SLOW_BLINK, UNDERLINED};

#[repr(C)]
#[derive(Clone, Copy)]
pub struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Default)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

#[repr(C)]
struct PollFd {
    fd: i32,
    events: i16,
    revents: i16,
}

extern "C" {
    fn tcgetattr(fd: i32, termios: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios: *const Termios) -> i32;
    fn cfmakeraw(termios: *mut Termios);
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
    fn poll(fds: *mut PollFd, nfds: u64, timeout: i32) -> i32;
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
}

const TIOCGWINSZ: u64 = 0x5413;
const TCSANOW: i32 = 0;
const POLLIN: i16 = 1;
const STDIN_FILENO: i32 = 0;
const STDOUT_FILENO: i32 = 1;

pub fn is_tty(fd: RawFd) -> bool {
    unsafe { isatty(fd) == 1 }
}

fn ioctl_size(fd: RawFd) -> Option<(u16, u16)> {
    let mut ws = Winsize::default();
    let r = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut Winsize) };
    if r == -1 {
        None
    } else {
        Some((ws.ws_col, ws.ws_row))
    }
}

fn tput_value(arg: &str) -> Option<u16> {
    let output = std::process::Command::new("tput").arg(arg).output().ok()?;
    let value = output
        .stdout
        .into_iter()
        .filter_map(|b| char::from(b).to_digit(10))
        .fold(0u16, |v, n| v.wrapping_mul(10).wrapping_add(n as u16));
    if value > 0 {
        Some(value)
    } else {
        None
    }
}

/// Terminal size (columns, rows), querying /dev/tty, stdout, then `tput`.
pub fn initial_size() -> io::Result<(u16, u16)> {
    let file = File::open("/dev/tty");
    let fd = match &file {
        Ok(f) => f.as_raw_fd(),
        Err(_) => STDOUT_FILENO,
    };
    if let Some(s) = ioctl_size(fd) {
        return Ok(s);
    }
    let err = io::Error::last_os_error();
    drop(file);
    let _ = err;
    match (tput_value("cols"), tput_value("lines")) {
        (Some(w), Some(h)) => Ok((w, h)),
        _ => Err(io::Error::last_os_error()),
    }
}

/// The terminal used for input and raw mode.
pub struct Tty {
    fd: RawFd,
    _file: Option<File>,
    original: Option<Termios>,
}

/// Open the controlling terminal for input (stdin if it is a tty).
pub fn open_tty() -> io::Result<(RawFd, Option<File>)> {
    if is_tty(STDIN_FILENO) {
        Ok((STDIN_FILENO, None))
    } else {
        let f = OpenOptions::new().read(true).write(true).open("/dev/tty")?;
        let fd = f.as_raw_fd();
        Ok((fd, Some(f)))
    }
}

impl Tty {
    pub fn enable_raw_mode() -> io::Result<Tty> {
        let (fd, file) = open_tty()?;
        let mut ios: Termios = unsafe { std::mem::zeroed() };
        if unsafe { tcgetattr(fd, &mut ios) } == -1 {
            return Err(io::Error::last_os_error());
        }
        let original = ios;
        unsafe { cfmakeraw(&mut ios) };
        if unsafe { tcsetattr(fd, TCSANOW, &ios) } == -1 {
            return Err(io::Error::last_os_error());
        }
        Ok(Tty { fd, _file: file, original: Some(original) })
    }

    pub fn disable_raw_mode(&mut self) {
        if let Some(orig) = self.original.take() {
            unsafe {
                tcsetattr(self.fd, TCSANOW, &orig);
            }
        }
    }

    pub fn size(&self) -> io::Result<(u16, u16)> {
        let file = File::open("/dev/tty");
        let fd = match &file {
            Ok(f) => f.as_raw_fd(),
            Err(_) => STDOUT_FILENO,
        };
        if let Some(s) = ioctl_size(fd) {
            return Ok(s);
        }
        if let Some(s) = ioctl_size(self.fd) {
            return Ok(s);
        }
        match (tput_value("cols"), tput_value("lines")) {
            (Some(w), Some(h)) => Ok((w, h)),
            _ => Err(io::Error::last_os_error()),
        }
    }

    /// Wait up to `timeout_ms` for input. Returns true if input is available.
    pub fn poll(&self, timeout_ms: i32) -> bool {
        let mut pfd = PollFd { fd: self.fd, events: POLLIN, revents: 0 };
        let r = unsafe { poll(&mut pfd, 1, timeout_ms) };
        r > 0 && (pfd.revents & POLLIN) != 0
    }

    /// Read available bytes (blocking until at least one is available).
    pub fn read_bytes(&self, buf: &mut Vec<u8>) -> io::Result<usize> {
        let mut tmp = [0u8; 1024];
        let n = unsafe { read(self.fd, tmp.as_mut_ptr(), tmp.len()) };
        if n < 0 {
            let e = io::Error::last_os_error();
            if e.kind() == io::ErrorKind::Interrupted || e.kind() == io::ErrorKind::WouldBlock {
                return Ok(0);
            }
            return Err(e);
        }
        buf.extend_from_slice(&tmp[..n as usize]);
        Ok(n as usize)
    }
}

impl Drop for Tty {
    fn drop(&mut self) {
        self.disable_raw_mode();
    }
}

#[allow(dead_code)]
pub fn leak_fd(f: File) -> RawFd {
    f.into_raw_fd()
}

// ---------------------------------------------------------------------------
// Output

fn color_fg(c: Color, out: &mut Vec<u8>) {
    match c {
        Color::Reset => out.extend_from_slice(b"39"),
        Color::Yellow => out.extend_from_slice(b"38;5;3"),
        Color::Rgb(r, g, b) => {
            let _ = write!(out, "38;2;{};{};{}", r, g, b);
        }
    }
}

fn color_bg(c: Color, out: &mut Vec<u8>) {
    match c {
        Color::Reset => out.extend_from_slice(b"49"),
        Color::Yellow => out.extend_from_slice(b"48;5;3"),
        Color::Rgb(r, g, b) => {
            let _ = write!(out, "48;2;{};{};{}", r, g, b);
        }
    }
}

fn sgr(out: &mut Vec<u8>, n: u8) {
    let _ = write!(out, "\x1b[{}m", n);
}

fn modifier_diff(from: u16, to: u16, out: &mut Vec<u8>) {
    let removed = from & !to;
    if removed & REVERSED != 0 {
        sgr(out, 27);
    }
    if removed & BOLD != 0 {
        sgr(out, 22);
        if to & DIM != 0 {
            sgr(out, 2);
        }
    }
    if removed & ITALIC != 0 {
        sgr(out, 23);
    }
    if removed & UNDERLINED != 0 {
