/// Encode a list of cell updates the way the crossterm backend does.
pub fn encode_updates(updates: &[(u16, u16, &Cell)], out: &mut Vec<u8>) {
    let mut fg = Color::Reset;
    let mut bg = Color::Reset;
    let mut modifier: u16 = 0;
    let mut last_pos: Option<(u16, u16)> = None;
    for &(x, y, cell) in updates {
        let contiguous = matches!(last_pos, Some((px, py)) if x == px + 1 && y == py);
        if !contiguous {
            let _ = write!(out, "\x1b[{};{}H", y + 1, x + 1);
        }
        last_pos = Some((x, y));
        if cell.modifier != modifier {
            modifier_diff(modifier, cell.modifier, out);
            modifier = cell.modifier;
        }
        if cell.fg != fg || cell.bg != bg {
            out.extend_from_slice(b"\x1b[");
            color_fg(cell.fg, out);
            out.push(b';');
            color_bg(cell.bg, out);
            out.push(b'm');
            fg = cell.fg;
            bg = cell.bg;
        }
        out.extend_from_slice(cell.symbol.as_bytes());
    }
    out.extend_from_slice(b"\x1b[39m\x1b[49m\x1b[59m\x1b[0m");
}

pub struct Screen {
    pub buffers: [Buffer; 2],
    pub current: usize,
    pub width: u16,
    pub height: u16,
}

impl Screen {
    pub fn new(width: u16, height: u16) -> Screen {
        let area = crate::buffer::Rect { x: 0, y: 0, width, height };
        Screen { buffers: [Buffer::empty(area), Buffer::empty(area)], current: 0, width, height }
    }

    pub fn resize(&mut self, width: u16, height: u16, out: &mut Vec<u8>) {
        let area = crate::buffer::Rect { x: 0, y: 0, width, height };
        self.buffers[0].resize(area);
        self.buffers[1].resize(area);
        self.width = width;
        self.height = height;
        out.extend_from_slice(b"\x1b[2J");
        self.buffers[1 - self.current].reset();
    }

    pub fn flush(&mut self, cursor: Option<(u16, u16)>, out: &mut Vec<u8>) {
        let prev = &self.buffers[1 - self.current];
        let cur = &self.buffers[self.current];
        let updates = prev.diff(cur);
        encode_updates(&updates, out);
        match cursor {
            None => out.extend_from_slice(b"\x1b[?25l"),
            Some((x, y)) => {
                out.extend_from_slice(b"\x1b[?25h");
                let _ = write!(out, "\x1b[{};{}H", y + 1, x + 1);
            }
        }
        self.buffers[1 - self.current].reset();
        self.current = 1 - self.current;
    }
}

pub fn write_stderr(bytes: &[u8]) {
    let mut e = io::stderr();
    let _ = e.write_all(bytes);
    let _ = e.flush();
}
