//! Application state and key handling.

use std::collections::HashMap;
use std::time::Duration;

use crate::flame::{FlameGraph, SearchPattern, ROOT};
use crate::input::{Key, KeyCode, CONTROL};
use crate::regex::{escape, Regex};
use crate::tinput::TextInput;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum View {
    Flamegraph,
    Top,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SortColumn {
    Total,
    Own,
}

#[derive(Clone, Copy, Debug)]
pub struct VisFrame {
    pub id: usize,
    pub level: usize,
    pub x: u16,
    pub width: u16,
}

pub struct FlameState {
    pub selected: usize,
    pub zoom: Option<usize>,
    pub level_offset: usize,
    pub frame_height: u16,
    pub frame_width: u16,
    pub visible: Vec<VisFrame>,
    pub num_levels: usize,
}

pub struct TopState {
    pub selected: usize,
    pub offset: usize,
    pub sort: SortColumn,
    pub height: u16,
}

pub struct App {
    pub running: bool,
    pub filename: String,
    pub flamegraph: FlameGraph,
    pub view: View,
    pub flame: FlameState,
    pub top: TopState,
    pub search: Option<SearchPattern>,
    pub input: Option<TextInput>,
    pub info: Option<String>,
    pub debug: bool,
    pub elapsed: HashMap<String, Duration>,
}

impl App {
    pub fn new(filename: String, flamegraph: FlameGraph, debug: bool) -> App {
        App {
            running: true,
            filename,
            flamegraph,
            view: View::Flamegraph,
            flame: FlameState {
                selected: ROOT,
                zoom: None,
                level_offset: 0,
                frame_height: 0,
                frame_width: 0,
                visible: Vec::new(),
                num_levels: 0,
            },
            top: TopState { selected: 0, offset: 0, sort: SortColumn::Own, height: 0 },
            search: None,
            input: None,
            info: None,
            debug,
            elapsed: HashMap::new(),
        }
    }

    pub fn set_search(&mut self, pattern: Option<SearchPattern>) {
        self.search = pattern;
        self.flamegraph.set_search(self.search.as_ref());
    }

    /// Sorted (unfiltered) list of top entries indices.
    pub fn sorted_top(&self) -> Vec<usize> {
        let top = &self.flamegraph.top;
        let mut idx: Vec<usize> = (0..top.len()).collect();
        match self.top.sort {
            SortColumn::Total => idx.sort_by(|&a, &b| (top[b].total, &top[b].name).cmp(&(top[a].total, &top[a].name))),
            SortColumn::Own => idx.sort_by(|&a, &b| (top[b].own, &top[b].name).cmp(&(top[a].own, &top[a].name))),
        }
        idx
    }

    /// Sorted and filtered list of top entries indices.
    pub fn filtered_top(&self) -> Vec<usize> {
        let idx = self.sorted_top();
        match &self.search {
            Some(p) => idx.into_iter().filter(|&i| p.re.is_match(&self.flamegraph.top[i].name)).collect(),
            None => idx,
        }
    }

    pub fn handle_key(&mut self, key: Key) {
        self.info = None;
        if let Some(input) = self.input.as_mut() {
            match key.code {
                KeyCode::Enter => {
                    let value = input.value.clone();
                    self.input = None;
                    self.apply_search_input(&value);
                }
                KeyCode::Esc => {
                    self.input = None;
                }
                _ => input.handle(&key),
            }
            return;
        }
        if let KeyCode::Char('c') | KeyCode::Char('C') = key.code {
            if key.modifiers == CONTROL {
                self.running = false;
                return;
            }
        }
        match self.view {
            View::Flamegraph => self.handle_flame_key(&key),
            View::Top => self.handle_top_key(&key),
        }
    }

    fn apply_search_input(&mut self, value: &str) {
        if value.is_empty() {
            self.set_search(None);
            return;
        }
        match Regex::new(value) {
            Ok(re) => self.set_search(Some(SearchPattern { pattern: value.to_string(), re })),
            Err(_) => {
                self.info = Some(format!("Invalid regex: {}", value));
            }
        }
    }

    fn search_exact(&mut self, name: &str) {
        let pattern = format!("^{}$", escape(name));
        if let Ok(re) = Regex::new(&pattern) {
            self.set_search(Some(SearchPattern { pattern, re }));
        }
    }

    fn handle_flame_key(&mut self, key: &Key) {
        match key.code {
            KeyCode::Char('q') => self.running = false,
            KeyCode::Char('j') | KeyCode::Down => self.move_down(),
            KeyCode::Char('k') | KeyCode::Up => self.move_up(),
            KeyCode::Char('h') | KeyCode::Left => self.move_horizontal(false),
            KeyCode::Char('l') | KeyCode::Right => self.move_horizontal(true),
            KeyCode::Char('f') => {
                let h = self.flame.frame_height as usize;
                let max = self.max_level_offset();
                self.flame.level_offset = (self.flame.level_offset + h).min(max);
            }
            KeyCode::Char('b') => {
                let h = self.flame.frame_height as usize;
                self.flame.level_offset = self.flame.level_offset.saturating_sub(h);
            }
            KeyCode::Char('G') => {
                self.flame.level_offset = self.max_level_offset();
            }
            KeyCode::Char('g') => {
                self.flame.level_offset = 0;
            }
            KeyCode::Enter => {
                let sel = self.flame.selected;
                if sel == ROOT {
                    self.reset_zoom();
                } else {
                    self.flame.zoom = Some(sel);
                }
            }
            KeyCode::Esc => self.reset_zoom(),
            KeyCode::Char('/') => {
                self.input = Some(TextInput::default());
            }
            KeyCode::Char('#') => {
                let sel = self.flame.selected;
                if sel != ROOT {
                    let name = self.flamegraph.stacks[sel].short_name.clone();
                    self.search_exact(&name);
                }
            }
            KeyCode::Char('n') => self.next_match(true),
            KeyCode::Char('N') => self.next_match(false),
            KeyCode::Char('r') => self.reset(),
            KeyCode::Tab => self.view = View::Top,
            _ => {}
        }
    }

    fn handle_top_key(&mut self, key: &Key) {
        match key.code {
            KeyCode::Char('q') => self.running = false,
            KeyCode::Char('j') | KeyCode::Down => {
                let n = self.filtered_top().len();
                self.top.selected = (self.top.selected + 1).min(n.saturating_sub(1));
            }
            KeyCode::Char('k') | KeyCode::Up => {
                self.top.selected = self.top.selected.saturating_sub(1);
            }
            KeyCode::Char('f') => {
                let n = self.filtered_top().len();
                let h = self.top.height as usize;
                self.top.selected = (self.top.selected + h).min(n.saturating_sub(1));
                self.top.offset = self.top.selected;
            }
            KeyCode::Char('b') => {
                let h = self.top.height as usize;
                self.top.selected = self.top.selected.saturating_sub(h);
                self.top.offset = self.top.selected;
            }
            KeyCode::Char('1') => self.top.sort = SortColumn::Total,
            KeyCode::Char('2') => self.top.sort = SortColumn::Own,
            KeyCode::Char('/') => {
                self.input = Some(TextInput::default());
            }
            KeyCode::Char('r') => self.reset(),
            KeyCode::Tab => self.view = View::Flamegraph,
            KeyCode::Enter => {
                let sorted = self.sorted_top();
                if let Some(&i) = sorted.get(self.top.selected) {
                    let name = self.flamegraph.top[i].name.clone();
                    self.search_exact(&name);
                    self.view = View::Flamegraph;
                }
            }
            _ => {}
        }
    }

    fn reset(&mut self) {
        self.flame.zoom = None;
        self.flame.selected = ROOT;
        self.flame.level_offset = 0;
        self.top.selected = 0;
        self.top.offset = 0;
        self.set_search(None);
    }

    fn reset_zoom(&mut self) {
        if let Some(z) = self.flame.zoom.take() {
            self.flame.selected = z;
        }
    }

    fn max_level_offset(&self) -> usize {
        self.flame.num_levels.saturating_sub(self.flame.frame_height as usize)
    }

    fn find_visible(&self, id: usize) -> Option<VisFrame> {
        self.flame.visible.iter().find(|f| f.id == id).copied()
    }

    fn select(&mut self, id: usize) {
        self.flame.selected = id;
        let level = self.flamegraph.stacks[id].level;
        let h = self.flame.frame_height as usize;
        if level < self.flame.level_offset {
            self.flame.level_offset = level;
        } else if h > 0 && level >= self.flame.level_offset + h {
            self.flame.level_offset = level + 1 - h;
        }
    }

    fn move_down(&mut self) {
        let sel = self.flame.selected;
        let mut best: Option<usize> = None;
        for &c in &self.flamegraph.stacks[sel].children {
            if self.find_visible(c).is_none() {
                continue;
            }
            match best {
                None => best = Some(c),
                Some(b) => {
                    if self.flamegraph.stacks[c].total >= self.flamegraph.stacks[b].total {
                        best = Some(c);
                    }
                }
            }
        }
        if let Some(c) = best {
            self.select(c);
        }
    }

    fn move_up(&mut self) {
        let sel = self.flame.selected;
        if let Some(p) = self.flamegraph.stacks[sel].parent {
            if self.find_visible(p).is_some() {
                self.select(p);
            }
        }
    }

    fn move_horizontal(&mut self, right: bool) {
        let Some(cur) = self.find_visible(self.flame.selected) else {
            return;
        };
        let mut best: Option<VisFrame> = None;
        for f in &self.flame.visible {
            if f.level != cur.level || f.id == cur.id {
                continue;
            }
            if right {
                if f.x > cur.x && best.map(|b| f.x < b.x).unwrap_or(true) {
                    best = Some(*f);
                }
            } else if f.x < cur.x && best.map(|b| f.x > b.x).unwrap_or(true) {
                best = Some(*f);
            }
        }
        if let Some(b) = best {
            self.select(b.id);
        }
    }

    fn next_match(&mut self, forward: bool) {
        if self.search.is_none() {
            return;
        }
        let Some(cur) = self.find_visible(self.flame.selected) else {
            return;
        };
        let key = |f: &VisFrame| (f.level, f.x);
        let cur_key = key(&cur);
        let mut target: Option<VisFrame> = None;
        for f in &self.flame.visible {
            if !self.flamegraph.stacks[f.id].hit {
                continue;
            }
            let k = key(f);
            if forward {
                if k > cur_key && target.map(|t| k < key(&t)).unwrap_or(true) {
                    target = Some(*f);
                }
            } else if k < cur_key && target.map(|t| k > key(&t)).unwrap_or(true) {
                target = Some(*f);
            }
        }
        if let Some(t) = target {
            self.select(t.id);
        }
    }
}
EOF
