//! Rendering of the application.

use crate::app::{App, SortColumn, View, VisFrame};
use crate::buffer::{Buffer, Color, Rect, Style, BOLD, REVERSED};
use crate::flame::{dim, stack_color, text_color, FlameGraph, ROOT};
use crate::layout::{split, Constraint};
use crate::text::{Alignment, Line, Span, Text};
use crate::widgets::{Block, Paragraph, Row, Table, BORDER_BOTTOM, BORDER_TOP};

const SELECTED_BG: (u8, u8, u8) = (250, 250, 250);
const HIT_BG: (u8, u8, u8) = (10, 35, 150);
const HIGHLIGHT_FG: Color = Color::Rgb(225, 10, 10);
const TOP_SELECTED_BG: Color = Color::Rgb(65, 65, 65);

fn rgb((r, g, b): (u8, u8, u8)) -> Color {
    Color::Rgb(r, g, b)
}

fn title_style() -> Style {
    Style::default().fg(Color::Yellow).bold()
}

fn status_block(title: &str, text: Text) -> Paragraph {
    Paragraph::new(text)
        .block(Block::new(BORDER_TOP).title(Line::from_spans(vec![Span::styled(format!("{} ", title), title_style())])))
        .wrap(true)
}

fn pct(a: u64, b: u64) -> f64 {
    a as f64 / b as f64 * 100.0
}

/// Compute the visible layout of the flamegraph frames for the given width.
pub fn compute_layout(fg: &FlameGraph, zoom: Option<usize>, width: u16) -> Vec<VisFrame> {
    let mut out = Vec::new();
    let wf = width as f64;
    fn rec(fg: &FlameGraph, id: usize, x: u16, wf: f64, out: &mut Vec<VisFrame>) {
        let w = wf as u16;
        if w == 0 {
            return;
        }
        let s = &fg.stacks[id];
        out.push(VisFrame { id, level: s.level, x, width: w });
        let mut off: u16 = 0;
        for &c in &s.children {
            let cwf = wf * (fg.stacks[c].total as f64 / s.total as f64);
            rec(fg, c, x.saturating_add(off), cwf, out);
            off = off.saturating_add(cwf as u16);
        }
    }
    match zoom {
        Some(z) => {
            if width > 0 {
                let mut anc = Vec::new();
                let mut p = fg.stacks[z].parent;
                while let Some(a) = p {
                    anc.push(a);
                    p = fg.stacks[a].parent;
                }
                for &a in anc.iter().rev() {
                    out.push(VisFrame { id: a, level: fg.stacks[a].level, x: 0, width });
                }
            }
            rec(fg, z, 0, wf, &mut out);
        }
        None => rec(fg, ROOT, 0, wf, &mut out),
    }
    out.sort_by_key(|f| (f.level, f.x));
    out
}

fn help_line(entries: &[(&str, &str)]) -> Line {
    let mut spans = Vec::new();
    for (key, desc) in entries {
        spans.push(Span::raw(" ["));
        spans.push(Span::styled(key.to_string(), title_style()));
        spans.push(Span::raw(format!(": {}]", desc)));
    }
    Line::from_spans(spans)
}

/// Render the whole UI into `buf`. Returns the cursor position if any.
pub fn render(app: &mut App, buf: &mut Buffer) -> Option<(u16, u16)> {
    let area = buf.area;
    let bold = Style::default().bold();

    // Header
    let filename_para = Paragraph::new(Text::from_lines(vec![Line::from_spans(vec![Span::styled(
        app.filename.clone(),
        bold,
    )])]))
    .wrap(true)
    .alignment(Alignment::Center);
    let header_lines = filename_para.line_count(area.width.saturating_sub(40));
    let header_height = (header_lines + 2).min(u16::MAX as usize) as u16;

    // Status blocks
    let mut blocks: Vec<Paragraph> = Vec::new();
    let mut search_block_index: Option<usize> = None;
    if let Some(input) = &app.input {
        search_block_index = Some(blocks.len());
        blocks.push(status_block("Search", Text::raw(input.value.clone())));
    } else {
        let root_total = app.flamegraph.root_total();
        let zoom_total = app.flame.zoom.map(|z| app.flamegraph.stacks[z].total);
        if let Some(p) = &app.search {
            let hit_total = app.flamegraph.hit_total;
            let text = match (app.view, zoom_total) {
                (View::Flamegraph, Some(zt)) => format!(
                    "\"{}\" [{} samples, {:.2}% of all, {:.2}% of zoomed]",
                    p.pattern,
                    hit_total,
                    pct(hit_total, root_total),
                    pct(hit_total, zt)
                ),
                _ => format!("\"{}\" [{} samples, {:.2}% of all]", p.pattern, hit_total, pct(hit_total, root_total)),
            };
            blocks.push(status_block("Match", Text::raw(text)));
        }
        if app.view == View::Flamegraph {
            // The selection is validated during flamegraph rendering; compute the
            // layout first so that the selected frame is up to date.
            prepare_flamegraph(app, area, header_height, &blocks);
            let sel = &app.flamegraph.stacks[app.flame.selected];
            let text = match zoom_total {
                Some(zt) => format!(
                    "{} [{} samples, {:.2}% of all, {:.2}% of zoomed]",
                    sel.display_name(),
                    sel.total,
                    pct(sel.total, root_total),
                    pct(sel.total, zt)
                ),
                None => format!("{} [{} samples, {:.2}% of all]", sel.display_name(), sel.total, pct(sel.total, root_total)),
            };
            blocks.push(status_block("Selected", Text::raw(text)));
        }
        if app.debug {
            let mut parts = Vec::new();
            for (k, v) in app.elapsed.iter() {
                parts.push(format!("{}:{:.2}ms", k, v.as_secs_f64() * 1000.0));
            }
            blocks.push(status_block("Debug", Text::raw(format!("Debug: {}", parts.join(" ")))));
        }
        if let Some(info) = &app.info {
            blocks.push(status_block("Info", Text::raw(info.clone())));
        }
    }

    let help = match app.view {
        View::Flamegraph => {
            let mut e = vec![
                ("hjkl", "move cursor"),
                ("f/b", "scroll"),
                ("enter/esc", "zoom"),
                ("/", "search"),
                ("#", "search like cursor"),
            ];
            if app.search.is_some() {
                e.push(("n/N", "next/prev search"));
            }
            e.push(("r", "reset"));
            e.push(("tab", "switch view"));
            e.push(("q", "quit"));
            help_line(&e)
        }
        View::Top => help_line(&[
            ("j/k", "move cursor"),
            ("f/b", "scroll"),
            ("1", "sort by total"),
            ("2", "sort by own"),
            ("/", "filter"),
            ("r", "reset"),
            ("tab", "switch view"),
            ("q", "quit"),
        ]),
    };

    let mut constraints = vec![Constraint::Length(header_height), Constraint::Fill(1)];
    for b in &blocks {
        let h = b.line_count(area.width).min(u16::MAX as usize) as u16;
        constraints.push(Constraint::Length(h));
    }
    constraints.push(Constraint::Length(2));
    let chunks = split(area, &constraints, 0, true);

    // Header rendering
    render_header(app, buf, chunks[0], filename_para);

    // Main view
    match app.view {
        View::Flamegraph => render_flamegraph(app, buf, chunks[1]),
        View::Top => render_top(app, buf, chunks[1]),
    }

    // Status blocks
    let mut cursor = None;
    for (i, b) in blocks.iter().enumerate() {
        let r = chunks[2 + i];
        b.render(r, buf);
        if Some(i) == search_block_index {
            if let Some(input) = &app.input {
                let x = r.x.saturating_add(input.cursor.min(u16::MAX as usize) as u16);
                let y = r.y.saturating_add(1);
                cursor = Some((x, y));
            }
        }
    }

    // Help
    let help_area = chunks[chunks.len() - 1];
    Paragraph::new(Text::from_lines(vec![help]))
        .block(Block::new(BORDER_TOP))
        .alignment(Alignment::Center)
        .render(help_area, buf);

    cursor
}

fn render_header(app: &App, buf: &mut Buffer, area: Rect, filename_para: Paragraph) {
    Block::new(BORDER_TOP | BORDER_BOTTOM).render(area, buf);
    let text_area = Rect::new(area.x, area.y.saturating_add(1), area.width, area.height);
    let cols = split(
        text_area,
        &[Constraint::Length(20), Constraint::Fill(1), Constraint::Length(16)],
        0,
        false,
    );
    let bold = Style::default().bold();
    let (fg_span, top_span) = match app.view {
        View::Flamegraph => (Span::styled("[Flamegraph]", title_style()), Span::styled("Top", bold)),
        View::Top => (Span::styled("Flamegraph", bold), Span::styled("[Top]", title_style())),
    };
    let left = Line::from_spans(vec![Span::raw(" "), fg_span, Span::raw(" | "), top_span, Span::raw(" ")]);
    Paragraph::new(Text::from_lines(vec![left])).render(cols[0], buf);
    filename_para.render(cols[1], buf);
    Paragraph::new(Text::from_lines(vec![Line::from_spans(vec![Span::styled("flamelens v0.3.1", bold)])]))
        .alignment(Alignment::Right)
        .render(cols[2], buf);
}

/// Compute the flamegraph layout for the area it will be rendered in and
/// validate the selection against the viewport.
fn prepare_flamegraph(app: &mut App, area: Rect, header_height: u16, blocks: &[Paragraph]) {
    // Compute the final flamegraph area with the selected block included.
    let mut constraints = vec![Constraint::Length(header_height), Constraint::Fill(1)];
    for b in blocks {
        constraints.push(Constraint::Length(b.line_count(area.width).min(u16::MAX as usize) as u16));
    }
    // Selected block: compute its height from the current selection (it is a
    // single wrapped line whose height may depend on the selection; use the
    // pre-validation selection text which has the same structure).
    let sel_text = selected_text(app);
    let sel_para = status_block("Selected", Text::raw(sel_text));
    constraints.push(Constraint::Length(sel_para.line_count(area.width).min(u16::MAX as usize) as u16));
    if app.debug {
        let mut parts = Vec::new();
        for (k, v) in app.elapsed.iter() {
            parts.push(format!("{}:{:.2}ms", k, v.as_secs_f64() * 1000.0));
        }
        let p = status_block("Debug", Text::raw(format!("Debug: {}", parts.join(" "))));
        constraints.push(Constraint::Length(p.line_count(area.width).min(u16::MAX as usize) as u16));
    }
    if let Some(info) = &app.info {
        let p = status_block("Info", Text::raw(info.clone()));
        constraints.push(Constraint::Length(p.line_count(area.width).min(u16::MAX as usize) as u16));
    }
    constraints.push(Constraint::Length(2));
    let chunks = split(area, &constraints, 0, true);
    update_flame_state(app, chunks[1]);
}

fn selected_text(app: &App) -> String {
    let root_total = app.flamegraph.root_total();
    let sel = &app.flamegraph.stacks[app.flame.selected];
    match app.flame.zoom.map(|z| app.flamegraph.stacks[z].total) {
        Some(zt) => format!(
            "{} [{} samples, {:.2}% of all, {:.2}% of zoomed]",
            sel.display_name(),
            sel.total,
            pct(sel.total, root_total),
            pct(sel.total, zt)
        ),
        None => format!("{} [{} samples, {:.2}% of all]", sel.display_name(), sel.total, pct(sel.total, root_total)),
    }
}

fn update_flame_state(app: &mut App, area: Rect) {
    app.flame.frame_height = area.height;
    app.flame.frame_width = area.width;
    app.flame.visible = compute_layout(&app.flamegraph, app.flame.zoom, area.width);
    app.flame.num_levels = app.flame.visible.iter().map(|f| f.level + 1).max().unwrap_or(0);
    let sel_level = app.flamegraph.stacks[app.flame.selected].level;
    let top = app.flame.level_offset;
    let h = area.height as usize;
    if sel_level < top || sel_level >= top + h {
        if let Some(f) = app.flame.visible.iter().find(|f| f.level == top) {
            app.flame.selected = f.id;
        }
    }
}

fn render_flamegraph(app: &mut App, buf: &mut Buffer, area: Rect) {
    update_flame_state(app, area);
    let top = app.flame.level_offset;
    let h = area.height as usize;
    let fg = &app.flamegraph;
    let zoom = app.flame.zoom;
    let selected = app.flame.selected;
    for f in &app.flame.visible {
        if f.level < top || f.level >= top + h {
            continue;
        }
        let y = area.y + (f.level - top) as u16;
        let x = area.x + f.x;
        let s = &fg.stacks[f.id];
        let is_selected = f.id == selected;
        let mut bg = if is_selected {
            SELECTED_BG
        } else if s.hit {
            HIT_BG
        } else {
            stack_color(&s.full_name)
        };
        if !is_selected {
            if let Some(z) = zoom {
                if fg.is_ancestor_or_self(f.id, z) {
                    bg = dim(bg);
                }
            }
        }
        let fgc = text_color(bg);
        let style = Style::default().fg(rgb(fgc)).bg(rgb(bg));
        let hl_style = style.fg(HIGHLIGHT_FG).bold();
        let name = s.display_name();
        let mut spans: Vec<Span> = Vec::new();
        let text_len;
        if f.width == 1 {
            spans.push(Span::styled(".", style));
            text_len = 1;
        } else {
            let text = format!(" {}", name);
            text_len = text.len();
            let matches = match (&app.search, s.hit) {
                (Some(p), true) => p.re.find_iter(name),
                _ => Vec::new(),
            };
            let mut pos = 0usize;
            for (ms, me) in matches {
                if me <= ms {
                    continue;
                }
                let (ms, me) = (ms + 1, me + 1);
                if ms > pos {
                    spans.push(Span::styled(text[pos..ms].to_string(), style));
                }
                spans.push(Span::styled(text[ms..me].to_string(), hl_style));
                pos = me;
            }
            if pos < text.len() {
                spans.push(Span::styled(text[pos..].to_string(), style));
            }
        }
        let pad = (f.width as usize).saturating_sub(text_len);
        if pad > 0 {
            spans.push(Span::styled(" ".repeat(pad), style));
        }
        set_line(buf, x, y, &spans, f.width);
    }
}

fn set_line(buf: &mut Buffer, x: u16, y: u16, spans: &[Span], max_width: u16) {
    let mut remaining = max_width;
    let mut x = x;
    for span in spans {
        if remaining == 0 {
            break;
        }
        let (nx, _) = buf.set_stringn(x, y, &span.content, remaining as usize, span.style);
        let w = nx.saturating_sub(x);
        x = nx;
        remaining = remaining.saturating_sub(w);
    }
}

fn render_top(app: &mut App, buf: &mut Buffer, area: Rect) {
    app.top.height = area.height;
    let rows_idx = app.filtered_top();
    let root_total = app.flamegraph.root_total();
    let top = &app.flamegraph.top;
    let mut rows = Vec::new();
    let mut total_w = 0usize;
    let mut own_w = 0usize;
    for &i in &rows_idx {
        let e = &top[i];
        let total_s = format!("{} ({:.2}%)", e.total, pct(e.total, root_total));
        let own_s = format!("{} ({:.2}%)", e.own, pct(e.own, root_total));
        total_w = total_w.max(total_s.len() + 2);
        own_w = own_w.max(own_s.len() + 2);
        let name_line = match &app.search {
            Some(p) => {
                let hl = Style::default().fg(HIGHLIGHT_FG).bold();
                let mut spans = Vec::new();
                let mut pos = 0usize;
                for (ms, me) in p.re.find_iter(&e.name) {
                    if me <= ms {
                        continue;
                    }
                    if ms > pos {
                        spans.push(Span::raw(e.name[pos..ms].to_string()));
                    }
                    spans.push(Span::styled(e.name[ms..me].to_string(), hl));
                    pos = me;
                }
                if pos < e.name.len() {
                    spans.push(Span::raw(e.name[pos..].to_string()));
                }
                Line::from_spans(spans)
            }
            None => Line::raw(e.name.clone()),
        };
        rows.push(Row {
            cells: vec![
                Text::from_lines(vec![Line::raw(total_s)]),
                Text::from_lines(vec![Line::raw(own_s)]),
                Text::from_lines(vec![name_line]),
            ],
            style: Style::default(),
        });
    }
    let (total_h, own_h) = match app.top.sort {
        SortColumn::Total => ("Total [▼]", "Own"),
        SortColumn::Own => ("Total", "Own [▼]"),
    };
    let header = Row {
        cells: vec![Text::raw(total_h), Text::raw(own_h), Text::raw("Name")],
        style: Style::default().add_modifier(BOLD | REVERSED),
    };
    let table = Table {
        header,
        rows,
        widths: vec![
            Constraint::Length(total_w.min(u16::MAX as usize) as u16),
            Constraint::Length(own_w.min(u16::MAX as usize) as u16),
            Constraint::Fill(1),
        ],
        column_spacing: 1,
        highlight_style: Style::default().bg(TOP_SELECTED_BG),
    };
    table.render(area, buf, Some(app.top.selected), app.top.offset);
}
