use crate::text::{Alignment, Line, Span, Text};
use crate::widgets::{Block, Paragraph, Row, Table, BORDER_BOTTOM, BORDER_TOP};

const SELECTED_BG: (u8, u8, u8) = (250, 250, 250);
const HIT_BG: (u8, u8, u8) = (10, 35, 150);
const HIGHLIGHT_FG: Color = Color::Rgb(225, 10, 10);
const TOP_SELECTED_BG: Color = Color::Rgb(65, 65, 65);

fn rgb((r, g, b): (u8, u8, u8)) -> Color {
    Color::Rgb(r, g, b)
}

fn title_style() -> Style {
    Style::default().fg(Color::Yellow).bold()
}

fn status_block(title: &str, text: Text) -> Paragraph {
    Paragraph::new(text)
        .block(Block::new(BORDER_TOP).title(Line::from_spans(vec![Span::styled(format!("{} ", title), title_style())])))
        .wrap(true)
}

fn pct(a: u64, b: u64) -> f64 {
    a as f64 / b as f64 * 100.0
}

/// Compute the visible layout of the flamegraph frames for the given width.
pub fn compute_layout(fg: &FlameGraph, zoom: Option<usize>, width: u16) -> Vec<VisFrame> {
    let mut out = Vec::new();
    let wf = width as f64;
    fn rec(fg: &FlameGraph, id: usize, x: u16, wf: f64, out: &mut Vec<VisFrame>) {
        let w = wf as u16;
        if w == 0 {
            return;
        }
        let s = &fg.stacks[id];
        out.push(VisFrame { id, level: s.level, x, width: w });
        let mut off: u16 = 0;
        for &c in &s.children {
            let cwf = wf * (fg.stacks[c].total as f64 / s.total as f64);
            rec(fg, c, x.saturating_add(off), cwf, out);
            off = off.saturating_add(cwf as u16);
        }
    }
    match zoom {
        Some(z) => {
            if width > 0 {
                let mut anc = Vec::new();
                let mut p = fg.stacks[z].parent;
                while let Some(a) = p {
                    anc.push(a);
                    p = fg.stacks[a].parent;
                }
                for &a in anc.iter().rev() {
                    out.push(VisFrame { id: a, level: fg.stacks[a].level, x: 0, width });
                }
            }
            rec(fg, z, 0, wf, &mut out);
        }
        None => rec(fg, ROOT, 0, wf, &mut out),
    }
    out.sort_by_key(|f| (f.level, f.x));
    out
}

fn help_line(entries: &[(&str, &str)]) -> Line {
