                    hit_total,
                    pct(hit_total, root_total),
                    pct(hit_total, zt)
                ),
                _ => format!("\"{}\" [{} samples, {:.2}% of all]", p.pattern, hit_total, pct(hit_total, root_total)),
            };
            blocks.push(status_block("Match", Text::raw(text)));
        }
        if app.view == View::Flamegraph {
            // The selection is validated during flamegraph rendering; compute the
            // layout first so that the selected frame is up to date.
            prepare_flamegraph(app, area, header_height, &blocks);
            let sel = &app.flamegraph.stacks[app.flame.selected];
            let text = match zoom_total {
                Some(zt) => format!(
                    "{} [{} samples, {:.2}% of all, {:.2}% of zoomed]",
                    sel.display_name(),
                    sel.total,
                    pct(sel.total, root_total),
                    pct(sel.total, zt)
                ),
                None => format!("{} [{} samples, {:.2}% of all]", sel.display_name(), sel.total, pct(sel.total, root_total)),
            };
            blocks.push(status_block("Selected", Text::raw(text)));
