        if app.debug {
            let mut parts = Vec::new();
            for (k, v) in app.elapsed.iter() {
                parts.push(format!("{}:{:.2}ms", k, v.as_secs_f64() * 1000.0));
            }
            blocks.push(status_block("Debug", Text::raw(format!("Debug: {}", parts.join(" ")))));
        }
        if let Some(info) = &app.info {
            blocks.push(status_block("Info", Text::raw(info.clone())));
        }
    }

    let help = match app.view {
        View::Flamegraph => {
            let mut e = vec![
                ("hjkl", "move cursor"),
                ("f/b", "scroll"),
                ("enter/esc", "zoom"),
                ("/", "search"),
                ("#", "search like cursor"),
            ];
            if app.search.is_some() {
                e.push(("n/N", "next/prev search"));
            }
            e.push(("r", "reset"));
            e.push(("tab", "switch view"));
            e.push(("q", "quit"));
            help_line(&e)
        }
        View::Top => help_line(&[
            ("j/k", "move cursor"),
            ("f/b", "scroll"),
            ("1", "sort by total"),
            ("2", "sort by own"),
            ("/", "filter"),
            ("r", "reset"),
            ("tab", "switch view"),
            ("q", "quit"),
        ]),
    };

    let mut constraints = vec![Constraint::Length(header_height), Constraint::Fill(1)];
    for b in &blocks {
        let h = b.line_count(area.width).min(u16::MAX as usize) as u16;
        constraints.push(Constraint::Length(h));
    }
    constraints.push(Constraint::Length(2));
    let chunks = split(area, &constraints, 0, true);

    // Header rendering
    render_header(app, buf, chunks[0], filename_para);

    // Main view
    match app.view {
        View::Flamegraph => render_flamegraph(app, buf, chunks[1]),
        View::Top => render_top(app, buf, chunks[1]),
    }

    // Status blocks
    let mut cursor = None;
    for (i, b) in blocks.iter().enumerate() {
        let r = chunks[2 + i];
        b.render(r, buf);
        if Some(i) == search_block_index {
            if let Some(input) = &app.input {
                let x = r.x.saturating_add(input.cursor.min(u16::MAX as usize) as u16);
                let y = r.y.saturating_add(1);
                cursor = Some((x, y));
            }
        }
    }

    // Help
    let help_area = chunks[chunks.len() - 1];
    Paragraph::new(Text::from_lines(vec![help]))
        .block(Block::new(BORDER_TOP))
        .alignment(Alignment::Center)
        .render(help_area, buf);

    cursor
}

