    let (blocks, search_block_index) = build_blocks(app);
    let mut cursor = None;
    for (i, b) in blocks.iter().enumerate() {
        let Some(&r) = chunks.get(2 + i) else { break };
        b.render(r, buf);
        if Some(i) == search_block_index {
            if let Some(input) = &app.input {
