//! Command line parsing compatible with the original tool's interface.

use std::io::{IsTerminal, Write};

pub struct Args {
    pub filename: Option<String>,
    pub sorted: bool,
    pub echo: bool,
    pub debug: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Id {
    Filename,
    Sorted,
    Echo,
    Debug,
    Help,
    Version,
    Group,
}

fn color_enabled(is_terminal: bool) -> bool {
    let var = |k: &str| std::env::var_os(k);
    if let Some(v) = var("NO_COLOR") {
        if !v.is_empty() {
            return false;
        }
    }
    if let Some(v) = var("CLICOLOR_FORCE") {
        if v != "0" {
            return true;
        }
    }
    let clicolor = var("CLICOLOR").map(|v| v != "0");
    if clicolor == Some(false) {
        return false;
    }
    if !is_terminal {
        return false;
    }
    let term_ok = match var("TERM") {
        Some(t) => t != "dumb",
        None => false,
    };
    term_ok || clicolor == Some(true) || var("CI").is_some()
}

struct Styler {
    color: bool,
}

impl Styler {
    fn bold(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[1m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn header(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[1m\x1b[4m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn error(&self) -> String {
        if self.color {
            "\x1b[1m\x1b[31merror:\x1b[0m".to_string()
        } else {
            "error:".to_string()
        }
    }
    fn invalid(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
    fn valid(&self, s: &str) -> String {
        if self.color {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

fn bin_name() -> String {
    std::env::args_os()
        .next()
        .and_then(|a| std::path::Path::new(&a).file_name().map(|f| f.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "flamelens".to_string())
}

fn help_text(st: &Styler, bin: &str) -> String {
    let mut s = String::new();
    s.push_str(&format!("{} {} [OPTIONS] [FILENAME]\n\n", st.header("Usage:"), st.bold(bin)));
    s.push_str(&format!("{}\n", st.header("Arguments:")));
    s.push_str("  [FILENAME]  Profile data filename\n\n");
    s.push_str(&format!("{}\n", st.header("Options:")));
    s.push_str(&format!("      {}   Whether to sort the stacks by time spent\n", st.bold("--sorted")));
    s.push_str(&format!(
        "      {}     Print data to stdout on exit. Useful when piping to other tools\n",
        st.bold("--echo")
    ));
    s.push_str(&format!("      {}    Show debug info\n", st.bold("--debug")));
    s.push_str(&format!("  {}, {}     Print help\n", st.bold("-h"), st.bold("--help")));
    s.push_str(&format!("  {}, {}  Print version\n", st.bold("-V"), st.bold("--version")));
    s
}

fn usage(st: &Styler, bin: &str, used: &[Id]) -> String {
    let mut s = format!("{} {}", st.header("Usage:"), st.bold(bin));
    if used.is_empty() {
        s.push_str(" [OPTIONS] [FILENAME]");
        return s;
    }
    let has_group = used.contains(&Id::Group);
    let mut opts: Vec<Id> = Vec::new();
    for &id in used {
        let member = matches!(id, Id::Filename | Id::Sorted | Id::Echo | Id::Debug);
        if id == Id::Group || (has_group && member) {
            continue;
        }
        if id == Id::Filename {
            continue;
        }
        if !opts.contains(&id) {
            opts.push(id);
        }
    }
    for id in opts {
        let name = match id {
            Id::Sorted => "--sorted",
            Id::Echo => "--echo",
            Id::Debug => "--debug",
            Id::Help => "--help",
            Id::Version => "--version",
            _ => continue,
        };
        s.push(' ');
        s.push_str(&st.bold(name));
    }
    if has_group {
        s.push_str(" <FILENAME|--sorted|--echo|--debug>");
    } else {
        s.push_str(" [FILENAME]");
    }
    s
}

fn exit_error(msg: String) -> ! {
    let mut e = std::io::stderr();
    let _ = e.write_all(msg.as_bytes());
    let _ = e.flush();
    std::process::exit(2);
}

/// strsim's jaro similarity.
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut a_flags = vec![false; a_len];
    let mut b_flags = vec![false; b_len];
    let mut matches = 0usize;
    for (i, ac) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = b_len.min(i + search_range + 1);
        for j in 0..max_bound {
            if min_bound <= j && *ac == b[j] && !b_flags[j] {
                a_flags[i] = true;
                b_flags[j] = true;
                matches += 1;
                break;
            }
        }
    }
    let mut transpositions = 0usize;
    if matches != 0 {
        let mut bi = b_flags.iter().zip(b.iter());
        for (af, ch1) in a_flags.iter().zip(a.iter()) {
            if *af {
                for (bf, ch2) in bi.by_ref() {
                    if !*bf {
                        continue;
                    }
                    if ch1 != ch2 {
                        transpositions += 1;
                    }
                    break;
                }
            }
        }
    }
    transpositions /= 2;
    if matches == 0 {
        0.0
    } else {
        ((matches as f64 / a_len as f64)
            + (matches as f64 / b_len as f64)
            + ((matches - transpositions) as f64 / matches as f64))
            / 3.0
    }
}

fn did_you_mean(arg: &str) -> Option<&'static str> {
    let longs = ["sorted", "echo", "debug", "help", "version"];
    let mut candidates: Vec<(f64, &'static str)> =
        longs.iter().map(|l| (jaro(arg, l), *l)).filter(|(c, _)| *c > 0.7).collect();
    candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    candidates.pop().map(|(_, l)| l)
}

pub fn parse() -> Args {
    let bin = bin_name();
    let err_st = Styler { color: color_enabled(std::io::stderr().is_terminal()) };
    let out_st = || Styler { color: color_enabled(std::io::stdout().is_terminal()) };
    let mut args = Args { filename: None, sorted: false, echo: false, debug: false };
    // matcher contents in insertion order (explicitly present)
    let mut present: Vec<Id> = Vec::new();
    let mut pending_filename = false;
    let mut trailing = false;

    let raw: Vec<String> = std::env::args_os().skip(1).map(|a| a.to_string_lossy().into_owned()).collect();

    let mark = |present: &mut Vec<Id>, id: Id| {
        present.push(id);
        if matches!(id, Id::Filename | Id::Sorted | Id::Echo | Id::Debug) && !present.contains(&Id::Group) {
            present.push(Id::Group);
        }
    };
    let resolve_pending = |present: &mut Vec<Id>, pending: &mut bool| {
        if *pending {
            *pending = false;
            mark(present, Id::Filename);
        }
    };

    let footer = |st: &Styler| format!("\n\nFor more information, try '{}'.\n", st.bold("--help"));

    for arg in raw.iter() {
        if !trailing && arg == "--" {
            trailing = true;
            resolve_pending(&mut present, &mut pending_filename);
            continue;
        }
        if !trailing && arg.starts_with("--") {
            let body = &arg[2..];
            let (name, value) = match body.split_once('=') {
                Some((n, v)) => (n, Some(v)),
                None => (body, None),
            };
            let id = match name {
                "sorted" => Some(Id::Sorted),
                "echo" => Some(Id::Echo),
                "debug" => Some(Id::Debug),
                "help" => Some(Id::Help),
                "version" => Some(Id::Version),
                _ => None,
            };
            match id {
                Some(id) => {
                    if let Some(v) = value {
                        let mut used: Vec<Id> = present.clone();
                        used.push(id);
                        resolve_pending(&mut present, &mut pending_filename);
                        let msg = format!(
                            "{} unexpected value '{}' for '{}' found; no more were expected\n\n{}{}",
                            err_st.error(),
                            err_st.invalid(v),
                            err_st.bold(&format!("--{}", name)),
                            usage(&err_st, &bin, &used),
                            footer(&err_st)
                        );
                        exit_error(msg);
                    }
                    resolve_pending(&mut present, &mut pending_filename);
                    match id {
                        Id::Help => {
                            let st = out_st();
                            print!("{}", help_text(&st, &bin));
                            let _ = std::io::stdout().flush();
                            std::process::exit(0);
                        }
                        Id::Version => {
                            println!("flamelens 0.3.1");
                            let _ = std::io::stdout().flush();
                            std::process::exit(0);
                        }
                        _ => {}
                    }
                    if present.contains(&id) {
                        let msg = format!(
                            "{} the argument '{}' cannot be used multiple times\n\n{}{}",
                            err_st.error(),
                            err_st.invalid(&format!("--{}", name)),
                            usage(&err_st, &bin, &[]),
                            footer(&err_st)
                        );
                        exit_error(msg);
                    }
                    match id {
                        Id::Sorted => args.sorted = true,
                        Id::Echo => args.echo = true,
                        Id::Debug => args.debug = true,
                        _ => {}
                    }
                    mark(&mut present, id);
                }
                None => {
                    resolve_pending(&mut present, &mut pending_filename);
                    let shown = format!("--{}", name);
                    let suggestion = did_you_mean(name);
                    let mut used = present.clone();
                    let tip = match suggestion {
                        Some(s) => {
                            let sid = match s {
                                "sorted" => Id::Sorted,
                                "echo" => Id::Echo,
                                "debug" => Id::Debug,
                                "help" => Id::Help,
                                _ => Id::Version,
                            };
                            if !used.contains(&sid) {
                                used.push(sid);
                            }
                            if matches!(sid, Id::Sorted | Id::Echo | Id::Debug) && !used.contains(&Id::Group) {
                                used.push(Id::Group);
                            }
                            format!(
                                "  {} a similar argument exists: '{}'",
                                err_st.valid("tip:"),
                                err_st.valid(&format!("--{}", s))
                            )
                        }
                        None => format!(
                            "  {} to pass '{}' as a value, use '{}'",
                            err_st.valid("tip:"),
                            err_st.invalid(&shown),
                            err_st.valid(&format!("-- {}", shown))
                        ),
                    };
                    let msg = format!(
                        "{} unexpected argument '{}' found\n\n{}\n\n{}{}",
                        err_st.error(),
                        err_st.invalid(&shown),
                        tip,
                        usage(&err_st, &bin, &used),
                        footer(&err_st)
                    );
                    exit_error(msg);
                }
            }
            continue;
        }
        if !trailing && arg.starts_with('-') && arg.len() > 1 {
            for c in arg[1..].chars() {
                match c {
                    'h' => {
                        let st = out_st();
                        print!("{}", help_text(&st, &bin));
                        let _ = std::io::stdout().flush();
                        std::process::exit(0);
                    }
                    'V' => {
                        println!("flamelens 0.3.1");
                        let _ = std::io::stdout().flush();
                        std::process::exit(0);
                    }
                    _ => {
                        let shown = format!("-{}", c);
                        let msg = format!(
                            "{} unexpected argument '{}' found\n\n  {} to pass '{}' as a value, use '{}'\n\n{}{}",
                            err_st.error(),
                            err_st.invalid(&shown),
                            err_st.valid("tip:"),
                            err_st.invalid(&shown),
                            err_st.valid(&format!("-- {}", shown)),
                            usage(&err_st, &bin, &[]),
                            footer(&err_st)
                        );
                        exit_error(msg);
                    }
                }
            }
            continue;
        }
        // positional
        if args.filename.is_some() {
            let msg = format!(
                "{} unexpected argument '{}' found\n\n{}{}",
                err_st.error(),
                err_st.invalid(arg),
                usage(&err_st, &bin, &[]),
                footer(&err_st)
            );
            exit_error(msg);
        }
        args.filename = Some(arg.clone());
        pending_filename = true;
    }
    args
}
