//! Background input reader initialization check.
//!
//! The terminal input reader is initialized on a separate thread as soon as
//! the terminal backend is created. When no terminal is available for input,
//! the reader cannot be initialized and the thread aborts with an error,
//! mirroring the behavior users would see from the original tool.
//!
//! The thread does not otherwise take part in event handling: input is read
//! and decoded by the main loop (see `main.rs`), which keeps the rendering and
//! the key handling strictly sequential.

use std::io;
use std::thread;

/// Error returned when the input reader cannot be initialized.
fn reader_error() -> io::Error {
    io::Error::new(io::ErrorKind::Other, "Failed to initialize input reader")
}

/// Try to initialize the input reader (open the terminal used for input).
fn init_reader() -> io::Result<bool> {
    match crate::term::open_tty() {
        Ok(_) => Ok(false),
        Err(_) => Err(reader_error()),
    }
}

/// Spawn the input reader thread.
///
/// The returned handle is detached; the thread finishes immediately after the
/// reader has been initialized successfully.
pub fn spawn_reader() {
    let _ = thread::spawn(move || {
        reader_loop();
    });
}

/// Body of the reader thread.
#[allow(clippy::needless_return)]
fn reader_loop() {
    loop {
        // poll for terminal readiness; this initializes the reader
        let _ready =
            init_reader().expect("failed to poll new events");
        return;
    }
}
