fn main() -> AppResult<()> {
    let args = cli::parse();
    let (filename, data) = read_input(&args.filename);
    if args.echo {
        println!("{}", data);
    }
    let tic = Instant::now();
    let flamegraph = FlameGraph::from_string(&data, args.sorted);
    let parse_time = tic.elapsed();
    let mut app = App::new(filename, flamegraph, args.debug);
    app.elapsed.insert("flamegraph".to_string(), parse_time);
    run(app)
}

static WINCH: AtomicBool = AtomicBool::new(false);

extern "C" fn on_winch(_sig: i32) {
    WINCH.store(true, Ordering::SeqCst);
}

extern "C" {
    fn signal(signum: i32, handler: usize) -> usize;
}

const SIGWINCH: i32 = 28;
const TICK: Duration = Duration::from_millis(250);

const ENTER: &[u8] = b"\x1b[?1049h";
const LEAVE: &[u8] = b"\x1b[?1049l\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1002l\x1b[?1000l";

fn restore_terminal() {
    let mut out = Vec::new();
    out.extend_from_slice(LEAVE);
    out.extend_from_slice(b"\x1b[?25h");
    term::write_stderr(&out);
}

fn run(mut app: App) -> AppResult<()> {
    // Create the terminal backend (queries the terminal size).
    let (width, height) = term::initial_size()?;
    event::spawn_reader();
    // Initialize the terminal user interface.
    let mut tty = Tty::enable_raw_mode()?;
    term::write_stderr(ENTER);
    let default_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(move |info| {
        restore_terminal();
        default_hook(info);
    }));
    unsafe {
        signal(SIGWINCH, on_winch as extern "C" fn(i32) as usize);
    }
    term::write_stderr(b"\x1b[?25l\x1b[2J");

    let mut screen = Screen::new(width, height);
    let mut pending: Vec<u8> = Vec::new();
    let mut queue: std::collections::VecDeque<input::Key> = std::collections::VecDeque::new();
    let mut last_tick = Instant::now();

    let result: AppResult<()> = (|| {
        while app.running {
            // draw
            let mut out = Vec::new();
            let (w, h) = tty.size()?;
            if w != screen.width || h != screen.height {
                screen.resize(w, h, &mut out);
            }
            let start = Instant::now();
            let cursor = {
                let buf = &mut screen.buffers[screen.current];
                ui::render(&mut app, buf)
            };
            screen.flush(cursor, &mut out);
            term::write_stderr(&out);
            app.elapsed.insert("render".to_string(), start.elapsed());

            // wait for the next event
            loop {
                if let Some(key) = queue.pop_front() {
                    let t = Instant::now();
                    app.handle_key(key);
                    app.elapsed.insert("handle_key_events".to_string(), t.elapsed());
                    break;
                }
                if WINCH.swap(false, Ordering::SeqCst) {
                    break;
                }
                let elapsed = last_tick.elapsed();
                if elapsed >= TICK {
                    last_tick = Instant::now();
                    break;
                }
                let timeout = (TICK - elapsed).as_millis() as i32 + 1;
                if tty.poll(timeout.max(1)) {
                    tty.read_bytes(&mut pending)?;
                    let more = tty.poll(0);
                    for ev in input::decode(&mut pending, more) {
                        if let Event::Key(k) = ev {
                            queue.push_back(k);
                        }
                    }
                } else if WINCH.swap(false, Ordering::SeqCst) {
                    break;
                }
            }
        }
        Ok(())
    })();

    tty.disable_raw_mode();
    restore_terminal();
    result
}
