/// Hash based color for a stack (inferno "hot" palette).
pub fn stack_color(full_name: &str) -> (u8, u8, u8) {
    let mut hasher = DefaultHasher::new();
    full_name.hash(&mut hasher);
    let v = hasher.finish() as f64 / u64::MAX as f64;
    let r = 205u8.wrapping_add((50.0 * v) as u8);
    let g = (230.0 * v) as u8;
    let b = (55.0 * v) as u8;
    (r, g, b)
}

pub fn dim((r, g, b): (u8, u8, u8)) -> (u8, u8, u8) {
    ((r as f64 * 0.4) as u8, (g as f64 * 0.4) as u8, (b as f64 * 0.4) as u8)
}

pub fn text_color((r, g, b): (u8, u8, u8)) -> (u8, u8, u8) {
    let lum = 0.2126 * r as f64 + 0.7152 * g as f64 + 0.0722 * b as f64;
    if lum > 128.0 {
        (10, 10, 10)
    } else {
        (225, 225, 225)
    }
}
