fn prop_matches(p: Prop, c: char) -> bool {
    let cp = c as u32;
    match p {
        Prop::Letter | Prop::Alphabetic => c.is_alphabetic(),
        Prop::Upper => c.is_uppercase(),
        Prop::Lower => c.is_lowercase(),
        Prop::TitleOrModifier => false,
        Prop::OtherLetter => c.is_alphabetic() && !c.is_uppercase() && !c.is_lowercase(),
        Prop::Mark => cp >= 0x300 && crate::unicode::char_width(c) == 0 && !c.is_control(),
        Prop::Number => c.is_numeric(),
        Prop::Decimal => c.is_ascii_digit() || (!c.is_ascii() && is_decimal_digit(c)),
        Prop::OtherNumber => c.is_numeric() && !(c.is_ascii_digit() || is_decimal_digit(c)),
        Prop::Punct => {
            c.is_ascii_punctuation() && !matches!(c, '$' | '+' | '<' | '=' | '>' | '^' | '`' | '|' | '~')
                || (0x2010..=0x2027).contains(&cp)
                || (0x2030..=0x205E).contains(&cp)
                || (0x3001..=0x3003).contains(&cp)
                || (0x3008..=0x3011).contains(&cp)
                || matches!(cp, 0xA1 | 0xA7 | 0xAB | 0xB6 | 0xB7 | 0xBB | 0xBF)
        }
        Prop::Symbol => {
            matches!(c, '$' | '+' | '<' | '=' | '>' | '^' | '`' | '|' | '~')
                || matches!(cp, 0xA2..=0xA6 | 0xA8 | 0xA9 | 0xAC | 0xAE..=0xB1 | 0xB4 | 0xD7 | 0xF7)
                || (0x2100..=0x214F).contains(&cp)
                || (0x2190..=0x23FF).contains(&cp)
                || (0x2500..=0x27BF).contains(&cp)
                || (0x1F000..=0x1FAFF).contains(&cp)
        }
        Prop::Separator => matches!(cp, 0x20 | 0xA0 | 0x1680 | 0x2000..=0x200A | 0x2028 | 0x2029 | 0x202F | 0x205F | 0x3000),
        Prop::SpaceSep => matches!(cp, 0x20 | 0xA0 | 0x1680 | 0x2000..=0x200A | 0x202F | 0x205F | 0x3000),
        Prop::Control => c.is_control(),
        Prop::Other => c.is_control() || (0xE000..=0xF8FF).contains(&cp) || matches!(cp, 0xAD | 0x200B..=0x200F | 0xFEFF),
        Prop::Whitespace => c.is_whitespace(),
        Prop::Ascii => c.is_ascii(),
        Prop::Any => true,
        Prop::Emoji => {
            matches!(c, '#' | '*' | '0'..='9')
                || matches!(cp, 0xA9 | 0xAE | 0x203C | 0x2049 | 0x2122 | 0x2139 | 0x2194..=0x2199 | 0x21A9 | 0x21AA)
                || (0x231A..=0x23FF).contains(&cp)
                || (0x2600..=0x27BF).contains(&cp)
                || (0x2934..=0x2935).contains(&cp)
                || (0x2B05..=0x2B55).contains(&cp)
                || (0x1F000..=0x1FAFF).contains(&cp)
        }
        Prop::Ranges(r) => r.iter().any(|&(a, b)| cp >= a && cp <= b),
    }
}

fn lookup_prop(name: &str) -> Option<Prop> {
    let name = match name.split_once(|c| c == '=' || c == ':') {
        Some((_, v)) => v,
        None => name,
    };
    let key: String = name
        .chars()
        .filter(|c| !c.is_whitespace() && *c != '_' && *c != '-')
        .collect::<String>()
        .to_lowercase();
    Some(match key.as_str() {
        "l" | "letter" => Prop::Letter,
        "lu" | "uppercaseletter" => Prop::Upper,
        "ll" | "lowercaseletter" => Prop::Lower,
        "lt" | "titlecaseletter" | "lm" | "modifierletter" | "lc" | "casedletter" => Prop::TitleOrModifier,
        "lo" | "otherletter" => Prop::OtherLetter,
        "m" | "mark" | "combiningmark" | "mn" | "nonspacingmark" | "mc" | "spacingmark" | "me" | "enclosingmark" => Prop::Mark,
        "n" | "number" => Prop::Number,
        "nd" | "decimalnumber" | "digit" => Prop::Decimal,
        "nl" | "letternumber" | "no" | "othernumber" => Prop::OtherNumber,
        "p" | "punctuation" | "punct" | "pc" | "connectorpunctuation" | "pd" | "dashpunctuation" | "ps"
        | "openpunctuation" | "pe" | "closepunctuation" | "pi" | "initialpunctuation" | "pf"
        | "finalpunctuation" | "po" | "otherpunctuation" => Prop::Punct,
        "s" | "symbol" | "sm" | "mathsymbol" | "sc" | "currencysymbol" | "sk" | "modifiersymbol" | "so"
        | "othersymbol" => Prop::Symbol,
        "z" | "separator" => Prop::Separator,
        "zs" | "spaceseparator" => Prop::SpaceSep,
        "zl" | "lineseparator" | "zp" | "paragraphseparator" => Prop::Separator,
        "cc" | "control" | "cntrl" => Prop::Control,
        "c" | "other" | "cf" | "format" | "co" | "privateuse" | "cn" | "unassigned" | "cs" | "surrogate" => Prop::Other,
        "whitespace" | "wspace" | "space" => Prop::Whitespace,
        "alphabetic" | "alpha" => Prop::Alphabetic,
        "uppercase" | "upper" => Prop::Upper,
        "lowercase" | "lower" => Prop::Lower,
        "ascii" => Prop::Ascii,
        "any" | "assigned" => Prop::Any,
        "emoji" => Prop::Emoji,
        "latin" | "latn" => Prop::Ranges(LATIN),
        "greek" | "grek" => Prop::Ranges(GREEK),
        "cyrillic" | "cyrl" => Prop::Ranges(CYRILLIC),
        "han" | "hani" => Prop::Ranges(HAN),
        "hiragana" | "hira" => Prop::Ranges(HIRAGANA),
        "katakana" | "kana" => Prop::Ranges(KATAKANA),
        "hangul" | "hang" => Prop::Ranges(HANGUL),
        "arabic" | "arab" => Prop::Ranges(ARABIC),
        "hebrew" | "hebr" => Prop::Ranges(HEBREW),
        "thai" => Prop::Ranges(THAI),
        "devanagari" | "deva" => Prop::Ranges(DEVANAGARI),
        _ => return None,
    })
}'''
