        let negated = self.eat('^');
        let mut lhs = self.parse_class_union(flags, true)?;
        loop {
            let op = match (self.peek(), self.peek_at(1)) {
                (Some('&'), Some('&')) => 1,
                (Some('-'), Some('-')) => 2,
                (Some('~'), Some('~')) => 3,
                (Some(']'), _) => {
                    self.pos += 1;
                    break;
                }
                (None, _) => return err("unclosed character class"),
                _ => return err("invalid character class"),
            };
            self.pos += 2;
            let rhs = self.parse_class_union(flags, false)?;
            let item = match op {
                1 => ClassItem::Intersect(Box::new(lhs), Box::new(rhs)),
                2 => ClassItem::Difference(Box::new(lhs), Box::new(rhs)),
                _ => ClassItem::SymDiff(Box::new(lhs), Box::new(rhs)),
            };
            lhs = Class { items: vec![item], negated: false, case_insensitive: flags.i };
        }
        lhs.negated = negated;
        Ok(lhs)
    }

    /// Parse class items (a union) until ']' or a set operator.
    fn parse_class_union(&mut self, flags: &Flags, mut first: bool) -> Result<Class, Error> {
        let mut cls = Class { items: Vec::new(), negated: false, case_insensitive: flags.i };
        loop {
            let Some(c) = self.peek() else {
                return err("unclosed character class");
            };
            if c == ']' && !first {
                break;
            }
            if !first || !cls.items.is_empty() {
                match (c, self.peek_at(1)) {
                    ('&', Some('&')) | ('-', Some('-')) | ('~', Some('~')) => break,
                    _ => {}
                }
            }
            first = false;
            // nested class or posix class
            if c == '[' {
                if self.peek_at(1) == Some(':') {
                    if let Some(item) = self.try_posix()? {
                        cls.items.push(item);
                        continue;
                    }
                }
                self.pos += 1;
                let nested = self.parse_class(flags)?;
                cls.items.push(ClassItem::Nested(Box::new(nested)));
                continue;
            }
            let start = self.parse_class_atom()?;
            match start {
                ClassAtom::Item(item) => cls.items.push(item),
                ClassAtom::Char(a) => {
                    // range?
                    if self.peek() == Some('-')
                        && self.peek_at(1).is_some()
                        && self.peek_at(1) != Some(']')
                        && self.peek_at(1) != Some('-')
                    {
                        self.pos += 1;
                        let end = self.parse_class_atom()?;
                        match end {
                            ClassAtom::Char(b) => {
                                if b < a {
                                    return err("invalid character class range");
                                }
                                cls.items.push(ClassItem::Range(a, b));
                            }
                            ClassAtom::Item(_) => return err("invalid character class range"),
                        }
                    } else {
                        cls.items.push(ClassItem::Range(a, a));
                    }
                }
            }
        }
        Ok(cls)
    }

